-- SLFF Trgovina v vseh jezikih slff.eu (shop/src/jezik.ts): sl, en, az, cs, da,
-- de, el, es, et, hr, hu, hy, lv, mk, pl, ro, sk, sr, tr, uk.
--
-- * izdelki, razlicice, motivi: stolpec prevodi = {"<jezik>": {ime, opis | oznaka,
--   primeri?}} za jezike razen sl/en (ti ostanejo v stolpcih *_sl, *_en). Polja,
--   sheme in možnosti motivov (JSON) dobijo prevode v vrstici: oznaka_<jezik>,
--   ime_<jezik>, privzeto_<jezik> (domač izmišljen primer) in moznosti_<jezik>
--   (slogani v jeziku). Brez prevoda velja angleščina. Primeri v prevodi.<jezik>.primeri
--   (tudi en) imajo domača izmišljena imena, ekipe in lige.
-- * jezik naročila (narocila.jezik, p_jezik v rezerviraj) sprejme vse jezike;
--   ime postavke, opis motiva in krog postave so v jeziku naročila.
-- * besedilo prvaka je slovensko le v slovenščini, sicer angleško (izris motiva
--   naslov prvaka zamenja z napisom v jeziku naročila, shop/src/motivi/napisi.ts).
-- * besedilo motiva sprejme tudi ș ț ə, grščino, cirilico in armenščino (pisave
--   motivov jih imajo); izbira sprejme niz iz katerega koli seznama moznosti*.
-- * javni RPC katalog, izdelek in motivi vrnejo še prevodi.
-- Prevodi so iz shop/src/jeziki in ustvarjeni z vsebino produkcije 31. 10. 2026
-- (aktivni in neaktivni izdelki, različice po oznaki, motivi).

alter table trgovina.izdelki add column prevodi jsonb not null default '{}' check (jsonb_typeof(prevodi) = 'object');
alter table trgovina.razlicice add column prevodi jsonb not null default '{}' check (jsonb_typeof(prevodi) = 'object');
alter table trgovina.motivi add column prevodi jsonb not null default '{}' check (jsonb_typeof(prevodi) = 'object');
comment on column trgovina.izdelki.prevodi is '{"<jezik>": {"ime", "opis"}} za jezike razen sl/en; brez prevoda velja angleščina.';
comment on column trgovina.razlicice.prevodi is '{"<jezik>": {"oznaka"}} za jezike razen sl/en.';
comment on column trgovina.motivi.prevodi is '{"<jezik>": {"ime", "opis", "primeri"?}} (primeri tudi za en); polja in sheme imajo prevode v vrstici (oznaka_<jezik>, ime_<jezik>, privzeto_<jezik>, moznosti_<jezik>).';

alter table trgovina.narocila drop constraint narocila_jezik_check;
alter table trgovina.narocila add constraint narocila_jezik_check
  check (jezik in ('sl', 'en', 'az', 'cs', 'da', 'de', 'el', 'es', 'et', 'hr', 'hu', 'hy', 'lv', 'mk', 'pl', 'ro', 'sk', 'sr', 'tr', 'uk'));

-- Besedilo iz stolpcev *_sl/*_en in prevodov: sl, en ali prevod (rezerva angleščina).
create function trgovina.prevod(p_sl text, p_en text, p_prevodi jsonb, p_polje text, p_jezik text) returns text
language sql immutable
as $$
  select case when p_jezik = 'sl' then p_sl
              else coalesce(nullif(p_prevodi->p_jezik->>p_polje, ''), p_en) end
$$;
revoke all on function trgovina.prevod(text, text, jsonb, text, text) from public, anon, authenticated;

-- --------------------------------------------------------------------------
-- Prvak: slovensko le v slovenščini (zadnja različica: 20261018190000)
-- --------------------------------------------------------------------------
create or replace function trgovina.besedilo_prvaka(p_liga text, p_sezona text, p_jezik text) returns text
language plpgsql immutable
as $$
declare
  v_pred text := case when p_jezik = 'sl' then 'Prvak mini lige ' else 'Mini league champion ' end;
  v_liga text := btrim(regexp_replace(coalesce(p_liga, ''), '\s+', ' ', 'g'));
  v_prostor int := 40 - char_length(v_pred) - 1 - char_length(p_sezona);
begin
  if v_liga = '' or public.prepovedano_besedilo(v_liga) is not null then
    return null;
  end if;
  if char_length(v_liga) > v_prostor then
    v_liga := rtrim(left(v_liga, v_prostor - 1)) || '…';
  end if;
  return v_pred || v_liga || ' ' || p_sezona;
end;
$$;

-- --------------------------------------------------------------------------
-- Preverjanje polj (zadnja različica: 20261019160000): črke vseh jezikov,
-- izbira iz katerega koli seznama moznosti* (moznosti, moznosti_de …).
-- Isti nabor črk v shop/src/personalizacija.ts (CRKE_MOTIVA).
-- --------------------------------------------------------------------------
create or replace function trgovina.vrednost_polja(f jsonb, v jsonb) returns jsonb
language plpgsql stable
as $$
declare
  v_txt text;
  v_st numeric;
begin
  case f->>'vrsta'
  when 'besedilo' then
    v_txt := case when jsonb_typeof(v) = 'string' then btrim(regexp_replace(v #>> '{}', '\s+', ' ', 'g')) end;
    if v_txt is null or char_length(v_txt) not between 1 and coalesce((f->>'max')::int, 12)
       or v_txt !~ '^[A-Za-zÀ-ÖØ-öø-žȘșȚțƏəͰ-ϿЀ-џҐ-ҟԱ-֏0-9 .''&!?-]+$' or v_txt !~ '[A-Za-zÀ-ÖØ-öø-žȘșȚțƏəͰ-ϿЀ-џҐ-ҟԱ-֏]'
       or public.prepovedano_besedilo(v_txt) is not null then
      raise exception 'Trgovina: besedilo v polju % ni dovoljeno.', f->>'kljuc' using hint = 'trgovina-personalizacija';
    end if;
    return to_jsonb(v_txt);
  when 'izbira' then
    -- moznosti: nizi ali {kljuc, ime_sl, ime_en}; shrani se niz oz. kljuc.
    if jsonb_typeof(v) <> 'string' or not exists (
         select 1 from jsonb_each(f) e
          where (e.key = 'moznosti' or e.key like 'moznosti\_%') and jsonb_typeof(e.value) = 'array'
            and (e.value @> jsonb_build_array(v) or e.value @> jsonb_build_array(jsonb_build_object('kljuc', v)))) then
      raise exception 'Trgovina: izbira v polju % ni na seznamu.', f->>'kljuc' using hint = 'trgovina-personalizacija';
    end if;
    return v;
  when 'barva' then
    -- moznosti: [{kljuc, hex, ime_sl, ime_en}]; shrani se kljuc.
    if jsonb_typeof(v) <> 'string' or not coalesce(f->'moznosti', '[]'::jsonb) @> jsonb_build_array(jsonb_build_object('kljuc', v)) then
      raise exception 'Trgovina: barva v polju % ni na seznamu.', f->>'kljuc' using hint = 'trgovina-personalizacija';
    end if;
    return v;
  when 'stevilka', 'leto' then
    v_st := case when jsonb_typeof(v) = 'number' then (v::text)::numeric end;
    if v_st is null or v_st <> trunc(v_st)
       or (f->>'vrsta' = 'stevilka' and v_st not between coalesce((f->>'min')::int, 0) and 99)
       or (f->>'vrsta' = 'leto' and v_st not between 1950 and extract(year from now())) then
      raise exception 'Trgovina: neveljavna številka v polju %.', f->>'kljuc' using hint = 'trgovina-personalizacija';
    end if;
    return to_jsonb(v_st::int);
  when 'datum' then
    v_txt := case when jsonb_typeof(v) = 'string' then v #>> '{}' end;
    if (case when v_txt ~ '^\d{4}-\d{2}-\d{2}$' and pg_input_is_valid(v_txt, 'date')
            then v_txt::date not between date '1950-01-01' and (current_date + interval '1 year')::date
            else true end) then
      raise exception 'Trgovina: neveljaven datum v polju %.', f->>'kljuc' using hint = 'trgovina-personalizacija';
    end if;
    return to_jsonb(v_txt);
  else
    raise exception 'Trgovina: neznana vrsta polja.' using hint = 'trgovina-personalizacija';
  end case;
end;
$$;
-- --------------------------------------------------------------------------
-- Rezervacija (zadnja različica: 20261018190000): vsi jeziki, ime postavke v jeziku naročila
-- --------------------------------------------------------------------------

create or replace function trgovina.rezerviraj(p_postavke jsonb, p_user uuid, p_jezik text, p_odjemalec text) returns jsonb
language plpgsql
as $$
declare
  v_narocilo trgovina.narocila;
  v_vrstic int;
  v_postavke jsonb := '[]'::jsonb;
  vr record;
  v_pers jsonb;
  v_dopl int;
  v_opis text;
  v_id bigint;
  v_znacka boolean := false;
  v_sporocilo text;
  v_namig text;
  v_koda text;
begin
  if jsonb_typeof(p_postavke) is distinct from 'array'
     or jsonb_array_length(p_postavke) not between 1 and 20
     or p_jezik is null or p_jezik not in ('sl', 'en', 'az', 'cs', 'da', 'de', 'el', 'es', 'et', 'hr', 'hu', 'hy', 'lv', 'mk', 'pl', 'ro', 'sk', 'sr', 'tr', 'uk')
     or p_odjemalec is null or p_odjemalec !~ '^[0-9a-f]{64}$'
     or exists (select 1 from jsonb_array_elements(p_postavke) e
                 where jsonb_typeof(e) <> 'object'
                    or jsonb_typeof(e->'razlicica_id') is distinct from 'number'
                    or jsonb_typeof(e->'kolicina') is distinct from 'number'
                    or (e->>'kolicina')::numeric not between 1 and 20
                    or (e->>'kolicina')::numeric <> trunc((e->>'kolicina')::numeric)
                    or (e->>'razlicica_id')::numeric not between -9223372036854775808 and 9223372036854775807
                    or (e->>'razlicica_id')::numeric <> trunc((e->>'razlicica_id')::numeric)
                    or coalesce(jsonb_typeof(e->'personalizacija'), 'null') not in ('object', 'null'))
  then
    raise exception 'Trgovina: neveljavna košarica.' using hint = 'trgovina-vnos';
  end if;

  if (select sum(kolicina) from jsonb_to_recordset(p_postavke) k(razlicica_id bigint, kolicina int)) > 50
     or (select count(distinct ((e->>'razlicica_id')::bigint, coalesce(nullif(e->'personalizacija', '{}'::jsonb), 'null'::jsonb)))
           from jsonb_array_elements(p_postavke) e) <> jsonb_array_length(p_postavke)
  then
    raise exception 'Trgovina: neveljavna košarica.' using hint = 'trgovina-vnos';
  end if;

  perform trgovina.pocisti();

  -- ponytail: brez zaklepa sta hkratni šesti zahtevi lahko obe sprejeti; meja je le zavora.
  if (select count(*) from trgovina.narocila n
       where n.stanje = 'caka_placilo' and n.rezervirano_do > now()
         and (n.user_id = p_user or (p_user is null and n.user_id is null and n.odjemalec = p_odjemalec))) >= 5
  then
    raise exception 'Trgovina: preveč odprtih naročil.' using hint = 'trgovina-omejitev';
  end if;

  -- Zaklep v stalnem vrstnem redu: hkratni nakupi istih različic čakajo drug
  -- na drugega in nato vidijo rezervacije, ki jih je prejšnji že potrdil.
  perform 1 from trgovina.razlicice r
   where r.id in (select razlicica_id from jsonb_to_recordset(p_postavke) k(razlicica_id bigint, kolicina int))
   order by r.id for update;

  select count(*) into v_vrstic
    from jsonb_to_recordset(p_postavke) k(razlicica_id bigint, kolicina int)
    join trgovina.razlicice r on r.id = k.razlicica_id and r.aktivna
    join trgovina.izdelki i on i.id = r.izdelek_id and i.aktiven;
  if v_vrstic <> jsonb_array_length(p_postavke) then
    raise exception 'Trgovina: izdelek ni na voljo.' using hint = 'trgovina-vnos';
  end if;

  if exists (select 1
               from (select razlicica_id, sum(kolicina) as kolicina
                       from jsonb_to_recordset(p_postavke) k(razlicica_id bigint, kolicina int) group by 1) k
               join trgovina.razlicice r on r.id = k.razlicica_id
               join trgovina.izdelki i on i.id = r.izdelek_id and not (i.po_narocilu or i.digitalni)
               join trgovina.razpolozljivo z on z.razlicica_id = k.razlicica_id
              where z.na_voljo < k.kolicina) then
    raise exception 'Trgovina: ni dovolj zaloge.' using hint = 'trgovina-zaloga';
  end if;

  -- Največ 5 darilnih bonov na naročilo (vsak je svoj kupon in koda v Stripe).
  if (select coalesce(sum(k.kolicina), 0)
        from jsonb_to_recordset(p_postavke) k(razlicica_id bigint, kolicina int)
        join trgovina.razlicice r on r.id = k.razlicica_id
        join trgovina.izdelki i on i.id = r.izdelek_id and i.digitalni) > 5 then
    raise exception 'Trgovina: največ 5 darilnih bonov na naročilo.' using hint = 'trgovina-vnos';
  end if;

  insert into trgovina.narocila (user_id, jezik, odjemalec) values (p_user, p_jezik, p_odjemalec)
  returning * into v_narocilo;

  for vr in
    select x.n, (x.el->>'kolicina')::int as kolicina, x.el->'personalizacija' as vhod,
           r.id as razlicica_id, r.cena, i.id as izdelek_id, i.tax_code, i.digitalni,
           trgovina.prevod(i.ime_sl, i.ime_en, i.prevodi, 'ime', p_jezik)
             || ' (' || trgovina.prevod(r.oznaka_sl, r.oznaka_en, r.prevodi, 'oznaka', p_jezik) || ')' as ime
      from jsonb_array_elements(p_postavke) with ordinality x(el, n)
      join trgovina.razlicice r on r.id = (x.el->>'razlicica_id')::bigint
      join trgovina.izdelki i on i.id = r.izdelek_id
     order by x.n
  loop
    begin
      select p.personalizacija, p.doplacilo, p.opis into v_pers, v_dopl, v_opis
        from trgovina.personaliziraj(vr.izdelek_id, vr.vhod, p_user, p_jezik) p;
      if v_pers->>'vrsta' = 'znacka' then
        vr.kolicina := 1;
        if v_znacka then
          raise exception 'Trgovina: značka je ena.' using hint = 'trgovina-personalizacija';
        end if;
        v_znacka := true;
        -- Ista pravica v drugem odprtem naročilu: hkratni rezervaciji se vrstita.
        perform 1 from public.preverjeni_racuni where id = (v_pers->>'preverjeni_racun_id')::bigint for update;
        if exists (select 1 from trgovina.postavke p
                     join trgovina.narocila n on n.id = p.narocilo_id
                    where n.id <> v_narocilo.id and n.stanje = 'caka_placilo' and n.rezervirano_do > now()
                      and p.personalizacija->>'vrsta' = 'znacka'
                      and p.personalizacija->>'preverjeni_racun_id' = v_pers->>'preverjeni_racun_id') then
          raise exception 'Trgovina: značka že čaka na plačilo.' using hint = 'trgovina-personalizacija';
        end if;
      end if;
      insert into trgovina.postavke (narocilo_id, razlicica_id, ime, cena, kolicina, personalizacija, doplacilo)
      values (v_narocilo.id, vr.razlicica_id, vr.ime, vr.cena, vr.kolicina, v_pers, v_dopl)
      returning id into v_id;
    exception when others then
      get stacked diagnostics v_sporocilo = message_text, v_namig = pg_exception_hint, v_koda = returned_sqlstate;
      raise exception using errcode = v_koda, message = v_sporocilo, hint = v_namig, detail = 'postavka:' || (vr.n - 1);
    end;
    v_postavke := v_postavke || jsonb_build_object(
      'postavka_id', v_id, 'razlicica_id', vr.razlicica_id, 'ime', vr.ime, 'cena', vr.cena, 'doplacilo', v_dopl,
      'kolicina', vr.kolicina, 'tax_code', vr.tax_code, 'digitalni', vr.digitalni, 'opis', v_opis, 'personalizacija', v_pers);
  end loop;

  return jsonb_build_object(
    'narocilo_id', v_narocilo.id,
    'javna_oznaka', v_narocilo.javna_oznaka,
    'rezervirano_do', v_narocilo.rezervirano_do,
    'postavke', v_postavke,
    'pismo', not exists (select 1 from jsonb_to_recordset(p_postavke) k(razlicica_id bigint, kolicina int)
                           join trgovina.razlicice r on r.id = k.razlicica_id
                           join trgovina.izdelki i on i.id = r.izdelek_id
                          where not i.pismo and not i.digitalni),
    'digitalno', not exists (select 1 from jsonb_to_recordset(p_postavke) k(razlicica_id bigint, kolicina int)
                               join trgovina.razlicice r on r.id = k.razlicica_id
                               join trgovina.izdelki i on i.id = r.izdelek_id
                              where not i.digitalni),
    'personalizirano', exists (select 1 from jsonb_array_elements(v_postavke) x
                                where jsonb_typeof(x->'personalizacija') = 'object'));
end;
$$;


-- --------------------------------------------------------------------------
-- Motiv (zadnja različica: 20261019160000): opis v jeziku naročila
-- --------------------------------------------------------------------------

create or replace function trgovina.personaliziraj_motiv(
  p_izdelek bigint, p_vhod jsonb, p_user uuid, p_jezik text,
  out personalizacija jsonb, out doplacilo int, out opis text
)
language plpgsql stable
as $$
declare
  m trgovina.motivi;
  f jsonb;
  v jsonb;
  v_polja jsonb;
  v_izhod jsonb := '{}'::jsonb;
  v_dodatno jsonb := '{}'::jsonb;
  v_kljuc text;
  v_txt text;
  v_st numeric;
  v_id bigint;
  v_opisi text[] := '{}';
  v_barve jsonb := '[]'::jsonb;
  v_liga bigint;
  v_sezona text;
begin
  if exists (select 1 from jsonb_object_keys(p_vhod) k where k not in ('motiv', 'polja', 'shema'))
     or jsonb_typeof(p_vhod->'motiv') is distinct from 'string'
     or coalesce(jsonb_typeof(p_vhod->'polja'), 'object') <> 'object'
     or jsonb_typeof(p_vhod->'shema') is distinct from 'string' then
    raise exception 'Trgovina: neveljavna personalizacija.' using hint = 'trgovina-personalizacija';
  end if;

  select mo.* into m
    from trgovina.motivi mo
   where mo.slug = p_vhod->>'motiv' and mo.aktiven;
  select mi.doplacilo into doplacilo
    from trgovina.motivi_izdelki mi where mi.motiv_id = m.id and mi.izdelek_id = p_izdelek;
  if m.id is null or doplacilo is null then
    raise exception 'Trgovina: motiv ni na voljo za ta izdelek.' using hint = 'trgovina-personalizacija';
  end if;

  if not exists (select 1 from jsonb_array_elements(m.sheme) s where s->>'kljuc' = p_vhod->>'shema') then
    raise exception 'Trgovina: neznana barvna shema.' using hint = 'trgovina-personalizacija';
  end if;

  v_polja := coalesce(p_vhod->'polja', '{}'::jsonb);
  if exists (select 1 from jsonb_object_keys(v_polja) k
              where not exists (select 1 from jsonb_array_elements(m.polja) x where x->>'kljuc' = k)) then
    raise exception 'Trgovina: neznano polje motiva.' using hint = 'trgovina-personalizacija';
  end if;

  for f in select x from jsonb_array_elements(m.polja) x loop
    v_kljuc := f->>'kljuc';
    v := v_polja->v_kljuc;
    if trgovina.prazno_polje(v) then
      if (f->>'obvezno')::boolean then
        raise exception 'Trgovina: polje % je obvezno.', v_kljuc using hint = 'trgovina-personalizacija';
      end if;
      continue;
    end if;

    case f->>'vrsta'
    when 'besedilo', 'izbira', 'stevilka', 'leto', 'datum' then
      v := trgovina.vrednost_polja(f, v);
      v_txt := v #>> '{}';
      -- izbira z oznakami: v opis gre oznaka v jeziku kupca, ne ključ.
      v_txt := coalesce((select trgovina.prevod(o->>'ime_sl', o->>'ime_en', jsonb_build_object(p_jezik, jsonb_build_object('ime', o->>('ime_' || p_jezik))), 'ime', p_jezik)
                           from jsonb_array_elements(coalesce(f->'moznosti', '[]'::jsonb)) o
                          where f->>'vrsta' = 'izbira' and jsonb_typeof(o) = 'object' and o->>'kljuc' = v_txt limit 1), v_txt);

    when 'barva' then
      v := trgovina.vrednost_polja(f, v);
      select trgovina.prevod(o->>'ime_sl', o->>'ime_en', jsonb_build_object(p_jezik, jsonb_build_object('ime', o->>('ime_' || p_jezik))), 'ime', p_jezik),
             v_barve || jsonb_build_array(o->'hex')
        into v_txt, v_barve
        from jsonb_array_elements(f->'moznosti') o where o->>'kljuc' = v #>> '{}' limit 1;

    when 'ekipa' then
      if p_user is null then
        raise exception 'Trgovina: za ta izdelek se prijavi.' using hint = 'trgovina-prijava';
      end if;
      v_st := case when jsonb_typeof(v) = 'number' then (v::text)::numeric end;
      v_id := null;
      if v_st = trunc(v_st) and v_st between -9223372036854775808 and 9223372036854775807 then
        select ft.id, ft.name into v_id, v_txt from public.fantasy_teams ft
         where ft.id = v_st::bigint and ft.owner_id = p_user and not ft.hisna;
      end if;
      if v_id is null then
        raise exception 'Trgovina: ekipa ni tvoja.' using hint = 'trgovina-personalizacija';
      end if;
      if public.je_mladinska_liga((select ft.competition_id from public.fantasy_teams ft where ft.id = v_id)) then
        raise exception 'Trgovina: ekipa mladinske lige ni za ta motiv.' using hint = 'trgovina-personalizacija';
      end if;
      if char_length(v_txt) > coalesce((f->>'max')::int, 24) or public.prepovedano_besedilo(v_txt) is not null then
        raise exception 'Trgovina: tega imena ekipe ne natisnemo.' using hint = 'trgovina-vnos';
      end if;
      v := to_jsonb(v_txt);
      v_dodatno := v_dodatno || jsonb_build_object('fantasy_team_id', v_id);

    when 'postava' then
      if p_user is null then
        raise exception 'Trgovina: za ta izdelek se prijavi.' using hint = 'trgovina-prijava';
      end if;
      v_st := case when jsonb_typeof(v) = 'number' then (v::text)::numeric end;
      if v_st is null or v_st <> trunc(v_st) or v_st not between -9223372036854775808 and 9223372036854775807 then
        raise exception 'Trgovina: ekipa ni tvoja.' using hint = 'trgovina-personalizacija';
      end if;
      begin
        v := trgovina.postava_ekipe(v_st::bigint, p_user);
      exception when raise_exception then
        get stacked diagnostics v_txt = pg_exception_hint;
        if v_txt = 'trgovina-postava-krog' then
          raise exception 'Trgovina: ekipa še nima končanega kroga s točkami.' using hint = 'trgovina-personalizacija';
        end if;
        raise;
      end;
      -- Opis (košarica, potrdilo, e-pošta) pove tudi krog posnetka: predogled je lahko starejši krog.
      v_txt := concat_ws(' · ', v->>'ekipa', trgovina.besedilo_kroga(v->>'krog', p_jezik));
      v_dodatno := v_dodatno || jsonb_build_object('fantasy_team_id', v->'fantasy_team_id', 'round_id', v->'round_id');

    when 'prvak' then
      if p_user is null then
        raise exception 'Trgovina: za ta izdelek se prijavi.' using hint = 'trgovina-prijava';
      end if;
      v_liga := null; v_txt := null; v_id := null; v_sezona := null;
      if jsonb_typeof(v) = 'object' and jsonb_typeof(v->'mini_liga_id') = 'number' and jsonb_typeof(v->'sezona') = 'string' then
        select p.mini_liga_id, p.sezona, p.fantasy_team_id, trgovina.besedilo_prvaka(p.ime, p.sezona, p_jezik)
          into v_liga, v_sezona, v_id, v_txt
          from trgovina.prvaki_uporabnika(p_user) p
         where p.mini_liga_id::numeric = (v->>'mini_liga_id')::numeric and p.sezona = v->>'sezona'
         limit 1;
      end if;
      if v_liga is null then
        raise exception 'Trgovina: nisi prvak te mini lige.' using hint = 'trgovina-personalizacija';
      elsif v_txt is null then
        raise exception 'Trgovina: imena te mini lige ne natisnemo.' using hint = 'trgovina-besedilo';
      end if;
      v := to_jsonb(v_txt);
      v_dodatno := v_dodatno || jsonb_build_object('fantasy_team_id', v_id, 'mini_liga_id', v_liga, 'sezona', v_sezona);

    else
      raise exception 'Trgovina: neznana vrsta polja.' using hint = 'trgovina-personalizacija';
    end case;

    v_izhod := v_izhod || jsonb_build_object(v_kljuc, v);
    v_opisi := v_opisi || v_txt;
  end loop;

  select x->>'kljuc', x->>'razlicna_od' into v_kljuc, v_txt
    from jsonb_array_elements(m.polja) x
   where x ? 'razlicna_od' and v_izhod ? (x->>'kljuc') and v_izhod->(x->>'kljuc') = v_izhod->(x->>'razlicna_od')
   limit 1;
  if found then
    raise exception 'Trgovina: polji % in % morata biti različni.', v_txt, v_kljuc using hint = 'trgovina-personalizacija';
  end if;

  opis := concat_ws(' · ', trgovina.prevod(m.ime_sl, m.ime_en, m.prevodi, 'ime', p_jezik),
                    nullif(array_to_string(v_opisi, ' · '), ''));
  -- barve: barve dresa (polja barva, po vrsti) ali barve sheme.
  personalizacija := jsonb_build_object('motiv', m.slug, 'polja', v_izhod, 'shema', p_vhod->>'shema', 'ime', opis,
                       'barve', case when v_barve <> '[]'::jsonb then v_barve
                                     else (select s->'barve' from jsonb_array_elements(m.sheme) s where s->>'kljuc' = p_vhod->>'shema') end)
                     || v_dodatno;
end;
$$;


-- --------------------------------------------------------------------------
-- Javno: katalog, izdelek in motivi vrnejo še prevodi
-- (zadnje različice: 20261019160000, 20261019080000, 20261019080000)
-- --------------------------------------------------------------------------

create function trgovina.prevodi_jezika(p jsonb, p_jezik text) returns jsonb
language sql immutable
as $$
  select case when p_jezik is null then p
              when p ? p_jezik then jsonb_build_object(p_jezik, p->p_jezik)
              else '{}'::jsonb end
$$;
revoke all on function trgovina.prevodi_jezika(jsonb, text) from public, anon, authenticated;

drop function public.trgovina_katalog();
drop function public.trgovina_izdelek(text);
drop function public.trgovina_motivi();

create function public.trgovina_katalog(p_jezik text default null) returns jsonb
language sql stable security definer set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'slug', i.slug, 'ime_sl', i.ime_sl, 'ime_en', i.ime_en, 'prevodi', trgovina.prevodi_jezika(i.prevodi, p_jezik), 'kategorija', i.kategorija,
           'slike', to_jsonb(i.slike), 'cena_od', v.cena_od, 'cena_do', v.cena_do,
           'na_voljo', case when i.po_narocilu or i.digitalni then 'da' else trgovina.oznaka_voljo(v.kosov) end,
           'po_narocilu', i.po_narocilu, 'digitalni', i.digitalni,
           'cena_z_motivom', v.cena_od + (select min(mi.doplacilo) from trgovina.motivi_izdelki mi
                                           join trgovina.motivi m on m.id = mi.motiv_id
                                          where mi.izdelek_id = i.id and m.aktiven))
         order by i.vrstni_red, i.id), '[]'::jsonb)
  from trgovina.izdelki i
  join lateral (
    select min(r.cena) as cena_od, max(r.cena) as cena_do, sum(greatest(z.na_voljo, 0)) as kosov
      from trgovina.razlicice r join trgovina.razpolozljivo z on z.razlicica_id = r.id
     where r.izdelek_id = i.id and r.aktivna
  ) v on v.cena_od is not null
  where i.aktiven
$$;


create function public.trgovina_izdelek(p_slug text, p_jezik text default null) returns jsonb
language sql stable security definer set search_path = public
as $$
  select jsonb_build_object(
    'slug', i.slug, 'ime_sl', i.ime_sl, 'ime_en', i.ime_en, 'opis_sl', i.opis_sl, 'opis_en', i.opis_en, 'prevodi', trgovina.prevodi_jezika(i.prevodi, p_jezik),
    'kategorija', i.kategorija, 'slike', to_jsonb(i.slike), 'pismo', i.pismo,
    'po_narocilu', i.po_narocilu, 'digitalni', i.digitalni, 'postopek', i.postopek,
    'personalizacije', coalesce((
      select jsonb_agg(jsonb_build_object('vrsta', x.vrsta, 'doplacilo', x.doplacilo, 'obvezna', x.obvezna) order by x.id)
        from trgovina.personalizacije x where x.izdelek_id = i.id), '[]'::jsonb),
    'motivi', coalesce((
      select jsonb_agg(jsonb_build_object('slug', m.slug, 'ime_sl', m.ime_sl, 'ime_en', m.ime_en,
                                          'opis_sl', m.opis_sl, 'opis_en', m.opis_en, 'prevodi', trgovina.prevodi_jezika(m.prevodi, p_jezik), 'cona', m.cona,
                                          'polja', m.polja, 'sheme', m.sheme, 'primeri', m.primeri,
                                          'doplacilo', mi.doplacilo)
                       order by m.vrstni_red, m.id)
        from trgovina.motivi_izdelki mi join trgovina.motivi m on m.id = mi.motiv_id and m.aktiven
       where mi.izdelek_id = i.id), '[]'::jsonb),
    'cone', trgovina.cone_json(i.id),
    'razlicice', coalesce((
      select jsonb_agg(jsonb_build_object('id', r.id, 'oznaka_sl', r.oznaka_sl, 'oznaka_en', r.oznaka_en, 'prevodi', trgovina.prevodi_jezika(r.prevodi, p_jezik),
                                          'cena', r.cena,
                                          'na_voljo', case when i.po_narocilu or i.digitalni then 'da'
                                                           else trgovina.oznaka_voljo(z.na_voljo) end)
                       order by r.vrstni_red, r.id)
        from trgovina.razlicice r join trgovina.razpolozljivo z on z.razlicica_id = r.id
       where r.izdelek_id = i.id and r.aktivna), '[]'::jsonb))
  from trgovina.izdelki i
  where i.slug = p_slug and i.aktiven
$$;


create function public.trgovina_motivi(p_jezik text default null) returns jsonb
language sql stable security definer set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'slug', m.slug, 'ime_sl', m.ime_sl, 'ime_en', m.ime_en, 'opis_sl', m.opis_sl, 'opis_en', m.opis_en, 'prevodi', trgovina.prevodi_jezika(m.prevodi, p_jezik),
           'cona', m.cona, 'polja', m.polja, 'sheme', m.sheme, 'primeri', m.primeri,
           'izdelki', coalesce((
             select jsonb_agg(jsonb_build_object('slug', i.slug, 'ime_sl', i.ime_sl, 'ime_en', i.ime_en, 'prevodi', trgovina.prevodi_jezika(i.prevodi, p_jezik),
                                                 'postopek', i.postopek, 'doplacilo', mi.doplacilo,
                                                 'cena_od', (select min(r.cena) from trgovina.razlicice r
                                                              where r.izdelek_id = i.id and r.aktivna),
                                                 'cone', trgovina.cone_json(i.id))
                              order by i.vrstni_red, i.id)
               from trgovina.motivi_izdelki mi join trgovina.izdelki i on i.id = mi.izdelek_id and i.aktiven
              where mi.motiv_id = m.id), '[]'::jsonb))
         order by m.vrstni_red, m.id), '[]'::jsonb)
    from trgovina.motivi m
   where m.aktiven
$$;


revoke all on function public.trgovina_katalog(text), public.trgovina_izdelek(text, text), public.trgovina_motivi(text) from public;
grant execute on function public.trgovina_katalog(text), public.trgovina_izdelek(text, text), public.trgovina_motivi(text) to anon, authenticated;
-- Krog posnetka postave v opisu postavke ("5. krog", "round 5", "Runde 5" …).
create function trgovina.besedilo_kroga(p_krog text, p_jezik text) returns text
language sql immutable
as $$
  select replace(coalesce($p${"sl":"{n}. krog","en":"round {n}","az":"Tur {n}","cs":"{n}. kolo","da":"{n}. runde","de":"{n}. Runde","el":"{n}η αγωνιστική","es":"jornada {n}","et":"{n}. voor","hr":"{n}. kolo","hu":"{n}. forduló","hy":"Տուր {n}","lv":"{n}. kārta","mk":"{n}. коло","pl":"{n}. kolejka","ro":"etapa {n}","sk":"{n}. kolo","sr":"{n}. kolo","tr":"{n}. hafta","uk":"{n}-й тур"}$p$::jsonb->>p_jezik, '{n}. krog'), '{n}', coalesce(p_krog, ''))
$$;
revoke all on function trgovina.besedilo_kroga(text, text) from public, anon, authenticated;

