update trgovina.izdelki set prevodi = $p${"az":{"ime":"SLFF fincanı","opis":"SLFF gerbli keramik fincan, 330 ml. Səhər qəhvəsi və turun xallarına baxmaq üçün."},"cs":{"ime":"Hrnek SLFF","opis":"Keramický hrnek s erbem SLFF, 330 ml. Na ranní kávu a kontrolu bodů z kola."},"da":{"ime":"SLFF krus","opis":"Keramikkrus med SLFF-emblemet, 330 ml. Til morgenkaffen og et kig på rundens point."},"de":{"ime":"SLFF Tasse","opis":"Keramiktasse mit SLFF-Wappen, 330 ml. Für den Morgenkaffee und den Blick auf die Punkte der Runde."},"el":{"ime":"Κούπα SLFF","opis":"Κεραμική κούπα με το έμβλημα του SLFF, 330 ml. Για τον πρωινό καφέ και τον έλεγχο των πόντων της αγωνιστικής."},"es":{"ime":"Taza SLFF","opis":"Taza de cerámica con el escudo de SLFF, 330 ml. Para el café de la mañana y repasar los puntos de la jornada."},"et":{"ime":"SLFF-i kruus","opis":"Keraamiline kruus SLFF-i embleemiga, 330 ml. Hommikukohvi ja vooru punktide ülevaatamise jaoks."},"hr":{"ime":"Šalica SLFF","opis":"Keramička šalica s grbom SLFF, 330 ml. Za jutarnju kavu i pregled bodova kola."},"hu":{"ime":"SLFF bögre","opis":"Kerámiabögre SLFF címerrel, 330 ml. A reggeli kávéhoz és a forduló pontjainak átnézéséhez."},"hy":{"ime":"SLFF գավաթ","opis":"Կերամիկական գավաթ՝ SLFF զինանշանով, 330 մլ։ Առավոտյան սուրճի և տուրի միավորները նայելու համար։"},"lv":{"ime":"SLFF krūze","opis":"Keramikas krūze ar SLFF ģerboni, 330 ml. Rīta kafijai un kārtas punktu pārbaudei."},"mk":{"ime":"SLFF шолја","opis":"Керамичка шолја со грбот на SLFF, 330 ml. За утринското кафе и проверката на поените од колото."},"pl":{"ime":"Kubek SLFF","opis":"Ceramiczny kubek z herbem SLFF, 330 ml. Do porannej kawy i sprawdzania punktów kolejki."},"ro":{"ime":"Cană SLFF","opis":"Cană ceramică cu emblema SLFF, 330 ml. Pentru cafeaua de dimineață și verificarea punctelor din etapă."},"sk":{"ime":"Hrnček SLFF","opis":"Keramický hrnček s erbom SLFF, 330 ml. Na rannú kávu a kontrolu bodov z kola."},"sr":{"ime":"SLFF šolja","opis":"Keramička šolja sa SLFF grbom, 330 ml. Za jutarnju kafu i pregled bodova kola."},"tr":{"ime":"SLFF kupa","opis":"SLFF armalı seramik kupa, 330 ml. Sabah kahvesi ve hafta puanlarına göz atmak için."},"uk":{"ime":"Чашка SLFF","opis":"Керамічна чашка з гербом SLFF, 330 мл. Для ранкової кави й перевірки очок туру."}}$p$::jsonb where slug = 'skodelica';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"SLFF pivə stəkanı","opis":"SLFF gerbli 0,5 l pivə stəkanı. Üçüncü hissə üçün."},"cs":{"ime":"Pivní sklenice SLFF","opis":"Pivní sklenice 0,5 l s erbem SLFF. Na třetí poločas."},"da":{"ime":"SLFF ølglas","opis":"Ølglas på 0,5 l med SLFF-emblemet. Til tredje halvleg."},"de":{"ime":"SLFF Bierglas","opis":"Bierglas 0,5 l mit SLFF-Wappen. Für die dritte Halbzeit."},"el":{"ime":"Ποτήρι μπίρας SLFF","opis":"Ποτήρι μπίρας 0,5 l με το έμβλημα του SLFF. Για το τρίτο ημίχρονο."},"es":{"ime":"Vaso de cerveza SLFF","opis":"Vaso de cerveza de 0,5 l con el escudo de SLFF. Para el tercer tiempo."},"et":{"ime":"SLFF-i õlleklaas","opis":"Õlleklaas 0,5 l SLFF-i embleemiga. Kolmanda poolaja jaoks."},"hr":{"ime":"Pivska čaša SLFF","opis":"Pivska čaša od 0,5 l s grbom SLFF. Za treće poluvrijeme."},"hu":{"ime":"SLFF söröspohár","opis":"0,5 literes söröspohár SLFF címerrel. A harmadik félidőre."},"hy":{"ime":"SLFF գարեջրի բաժակ","opis":"Գարեջրի բաժակ 0,5 լ՝ SLFF զինանշանով։ Երրորդ խաղակեսի համար։"},"lv":{"ime":"SLFF alus glāze","opis":"Alus glāze 0,5 l ar SLFF ģerboni. Trešajam puslaikam."},"mk":{"ime":"SLFF чаша за пиво","opis":"Чаша за пиво од 0,5 l со грбот на SLFF. За третото полувреме."},"pl":{"ime":"Szklanka do piwa SLFF","opis":"Szklanka do piwa 0,5 l z herbem SLFF. Na trzecią połowę."},"ro":{"ime":"Halbă de bere SLFF","opis":"Pahar de bere de 0,5 l cu emblema SLFF. Pentru repriza a treia."},"sk":{"ime":"Pivový pohár SLFF","opis":"Pivový pohár 0,5 l s erbom SLFF. Na tretí polčas."},"sr":{"ime":"SLFF čaša za pivo","opis":"Čaša za pivo od 0,5 l sa SLFF grbom. Za treće poluvreme."},"tr":{"ime":"SLFF bira bardağı","opis":"SLFF armalı 0,5 l bira bardağı. Üçüncü devre için."},"uk":{"ime":"Пивний келих SLFF","opis":"Пивний келих 0,5 л з гербом SLFF. Для третього тайму."}}$p$::jsonb where slug = 'pivski-kozarec';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"SLFF stikerləri","opis":"SLFF stiker dəsti: gerb, loqo və maskot. Məktubla göndəririk."},"cs":{"ime":"Samolepky SLFF","opis":"Sada samolepek SLFF: erb, logo a maskot. Posíláme dopisem."},"da":{"ime":"SLFF klistermærker","opis":"Sæt med SLFF-klistermærker: emblem, logo og maskot. Sendes som brev."},"de":{"ime":"SLFF Sticker","opis":"Stickerset SLFF: Wappen, Logo und Maskottchen. Versand als Brief."},"el":{"ime":"Αυτοκόλλητα SLFF","opis":"Σετ αυτοκόλλητων SLFF: έμβλημα, λογότυπο και μασκότ. Αποστέλλεται ως επιστολή."},"es":{"ime":"Pegatinas SLFF","opis":"Juego de pegatinas de SLFF: escudo, logotipo y mascota. Se envían por carta."},"et":{"ime":"SLFF-i kleebised","opis":"SLFF-i kleebiste komplekt: embleem, logo ja maskott. Saadame kirjaga."},"hr":{"ime":"Naljepnice SLFF","opis":"Komplet naljepnica SLFF: grb, logotip i maskota. Šaljemo pismom."},"hu":{"ime":"SLFF matricák","opis":"SLFF matricakészlet: címer, logó és kabala. Levélként küldjük."},"hy":{"ime":"SLFF կպչուն պիտակներ","opis":"SLFF կպչուն պիտակների հավաքածու՝ զինանշան, լոգո և թալիսման։ Ուղարկում ենք նամակով։"},"lv":{"ime":"SLFF uzlīmes","opis":"SLFF uzlīmju komplekts: ģerbonis, logotips un talismans. Sūtām vēstulē."},"mk":{"ime":"SLFF налепници","opis":"Комплет SLFF налепници: грб, лого и маскота. Ги испраќаме со писмо."},"pl":{"ime":"Naklejki SLFF","opis":"Zestaw naklejek SLFF: herb, logo i maskotka. Wysyłamy listem."},"ro":{"ime":"Autocolante SLFF","opis":"Set de autocolante SLFF: emblemă, logo și mascotă. Le trimitem prin scrisoare."},"sk":{"ime":"Nálepky SLFF","opis":"Sada nálepiek SLFF: erb, logo a maskot. Posielame listom."},"sr":{"ime":"SLFF nalepnice","opis":"Komplet SLFF nalepnica: grb, logo i maskota. Šaljemo pismom."},"tr":{"ime":"SLFF çıkartmalar","opis":"SLFF çıkartma seti: arma, logo ve maskot. Mektupla gönderilir."},"uk":{"ime":"Наліпки SLFF","opis":"Набір наліпок SLFF: герб, логотип і талісман. Надсилаємо листом."}}$p$::jsonb where slug = 'nalepke';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Komanda adı yazılmış futbolka","opis":"Arxasında fantasy komandanın adı və istəyə görə nömrə olan futbolka. Komandalarından birini seçirsən."},"cs":{"ime":"Tričko s názvem týmu","opis":"Tričko s názvem tvého fantasy týmu na zádech a podle přání s číslem. Vybereš jeden ze svých týmů."},"da":{"ime":"T-shirt med holdnavn","opis":"T-shirt med dit fantasyholds navn på ryggen og et nummer, hvis du vil. Du vælger et af dine hold."},"de":{"ime":"T-Shirt mit Teamnamen","opis":"T-Shirt mit dem Namen deines Fantasy-Teams auf dem Rücken und auf Wunsch einer Nummer. Du wählst eines deiner Teams."},"el":{"ime":"Μπλουζάκι με όνομα ομάδας","opis":"Μπλουζάκι με το όνομα της fantasy ομάδας σου στην πλάτη και, αν θέλεις, αριθμό. Διαλέγεις μία από τις ομάδες σου."},"es":{"ime":"Camiseta con el nombre del equipo","opis":"Camiseta con el nombre de tu equipo fantasy en la espalda y, si quieres, un dorsal. Elige uno de tus equipos."},"et":{"ime":"Meeskonna nimega T-särk","opis":"T-särk sinu fantaasiameeskonna nimega seljal ja soovi korral numbriga. Vali üks oma meeskondadest."},"hr":{"ime":"Majica s imenom momčadi","opis":"Majica s imenom tvoje fantasy momčadi na leđima i po želji s brojem. Odabireš jednu od svojih momčadi."},"hu":{"ime":"Póló a csapat nevével","opis":"Póló a fantasy csapatod nevével a hátán, kérésre számmal. A csapataid közül választhatsz egyet."},"hy":{"ime":"Շապիկ թիմի անունով","opis":"Շապիկ՝ մեջքին քո ֆենթեզի թիմի անունով և ցանկության դեպքում՝ համարով։ Ընտրում ես քո թիմերից մեկը։"},"lv":{"ime":"T-krekls ar komandas nosaukumu","opis":"T-krekls ar tavas fantasy komandas nosaukumu uz muguras un pēc vēlēšanās ar numuru. Izvēlies vienu no savām komandām."},"mk":{"ime":"Маица со име на тимот","opis":"Маица со името на твојот фантази тим на грбот и по желба со број. Избираш еден од своите тимови."},"pl":{"ime":"Koszulka z nazwą drużyny","opis":"Koszulka z nazwą twojej drużyny fantasy na plecach i opcjonalnie z numerem. Wybierasz jedną ze swoich drużyn."},"ro":{"ime":"Tricou cu numele echipei","opis":"Tricou cu numele echipei tale fantasy pe spate și, dacă vrei, un număr. Alegi una dintre echipele tale."},"sk":{"ime":"Tričko s názvom tímu","opis":"Tričko s názvom tvojho fantasy tímu na chrbte a podľa želania s číslom. Vyberieš jeden zo svojich tímov."},"sr":{"ime":"Majica sa imenom tima","opis":"Majica sa imenom tvog fantasy tima na leđima i po želji sa brojem. Biraš jedan od svojih timova."},"tr":{"ime":"Takım adlı tişört","opis":"Sırtında fantezi takımının adı ve isteğe bağlı numara olan tişört. Takımlarından birini seçersin."},"uk":{"ime":"Футболка з назвою команди","opis":"Футболка з назвою твоєї фентезі-команди на спині й за бажанням із номером. Обираєш одну зі своїх команд."}}$p$::jsonb where slug = 'majica-ime-ekipe';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Ad və nömrəli futbolka","opis":"Arxasında istədiyin ad (12 simvola qədər) və istəyə görə nömrə olan futbolka."},"cs":{"ime":"Tričko se jménem a číslem","opis":"Tričko s libovolným jménem (až 12 znaků) a podle přání s číslem na zádech."},"da":{"ime":"T-shirt med navn og nummer","opis":"T-shirt med et valgfrit navn (op til 12 tegn) og et nummer på ryggen, hvis du vil."},"de":{"ime":"T-Shirt mit Name und Nummer","opis":"T-Shirt mit einem Namen deiner Wahl (bis 12 Zeichen) und auf Wunsch einer Nummer auf dem Rücken."},"el":{"ime":"Μπλουζάκι με όνομα και αριθμό","opis":"Μπλουζάκι με όνομα της επιλογής σου (έως 12 χαρακτήρες) και, αν θέλεις, αριθμό στην πλάτη."},"es":{"ime":"Camiseta con nombre y dorsal","opis":"Camiseta con el nombre que quieras (hasta 12 caracteres) y, si quieres, un dorsal en la espalda."},"et":{"ime":"Nime ja numbriga T-särk","opis":"T-särk vabalt valitud nimega (kuni 12 tähemärki) ja soovi korral numbriga seljal."},"hr":{"ime":"Majica s imenom i brojem","opis":"Majica s proizvoljnim imenom (do 12 znakova) i po želji brojem na leđima."},"hu":{"ime":"Póló névvel és számmal","opis":"Póló tetszőleges névvel (legfeljebb 12 karakter) és kérésre számmal a hátán."},"hy":{"ime":"Շապիկ անունով և համարով","opis":"Շապիկ՝ մեջքին կամայական անունով (մինչև 12 նիշ) և ցանկության դեպքում՝ համարով։"},"lv":{"ime":"T-krekls ar vārdu un numuru","opis":"T-krekls ar brīvi izvēlētu vārdu (līdz 12 rakstzīmēm) un pēc vēlēšanās numuru uz muguras."},"mk":{"ime":"Маица со име и број","opis":"Маица со произволно име (до 12 знаци) и по желба број на грбот."},"pl":{"ime":"Koszulka z imieniem i numerem","opis":"Koszulka z dowolnym imieniem (do 12 znaków) i opcjonalnie numerem na plecach."},"ro":{"ime":"Tricou cu nume și număr","opis":"Tricou cu un nume la alegere (până la 12 caractere) și, dacă vrei, un număr pe spate."},"sk":{"ime":"Tričko s menom a číslom","opis":"Tričko s ľubovoľným menom (do 12 znakov) a podľa želania s číslom na chrbte."},"sr":{"ime":"Majica sa imenom i brojem","opis":"Majica sa proizvoljnim imenom (do 12 znakova) i po želji brojem na leđima."},"tr":{"ime":"İsim ve numaralı tişört","opis":"Sırtında istediğin bir isim (en fazla 12 karakter) ve isteğe bağlı numara olan tişört."},"uk":{"ime":"Футболка з ім’ям і номером","opis":"Футболка з довільним ім’ям (до 12 символів) і за бажанням номером на спині."}}$p$::jsonb where slug = 'majica-ime-stevilka';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Adlı fincan","opis":"SLFF gerbi və sənin adın (12 simvola qədər) olan fincan."},"cs":{"ime":"Hrnek se jménem","opis":"Hrnek s erbem SLFF a tvým jménem (až 12 znaků)."},"da":{"ime":"Krus med navn","opis":"Krus med SLFF-emblemet og dit navn (op til 12 tegn)."},"de":{"ime":"Tasse mit Namen","opis":"Tasse mit SLFF-Wappen und deinem Namen (bis 12 Zeichen)."},"el":{"ime":"Κούπα με όνομα","opis":"Κούπα SLFF με το όνομά σου (έως 12 χαρακτήρες)."},"es":{"ime":"Taza con nombre","opis":"Taza con el escudo de SLFF y tu nombre (hasta 12 caracteres)."},"et":{"ime":"Nimega kruus","opis":"Kruus SLFF-i embleemi ja sinu nimega (kuni 12 tähemärki)."},"hr":{"ime":"Šalica s imenom","opis":"Šalica s grbom SLFF i tvojim imenom (do 12 znakova)."},"hu":{"ime":"Bögre névvel","opis":"Bögre SLFF címerrel és a neveddel (legfeljebb 12 karakter)."},"hy":{"ime":"Գավաթ անունով","opis":"Գավաթ՝ SLFF զինանշանով և քո անունով (մինչև 12 նիշ)։"},"lv":{"ime":"Krūze ar vārdu","opis":"Krūze ar SLFF ģerboni un tavu vārdu (līdz 12 rakstzīmēm)."},"mk":{"ime":"Шолја со име","opis":"Шолја со грбот на SLFF и твоето име (до 12 знаци)."},"pl":{"ime":"Kubek z imieniem","opis":"Kubek z herbem SLFF i twoim imieniem (do 12 znaków)."},"ro":{"ime":"Cană cu nume","opis":"Cană cu emblema SLFF și numele tău (până la 12 caractere)."},"sk":{"ime":"Hrnček s menom","opis":"Hrnček s erbom SLFF a tvojím menom (do 12 znakov)."},"sr":{"ime":"Šolja sa imenom","opis":"Šolja sa SLFF grbom i tvojim imenom (do 12 znakova)."},"tr":{"ime":"Kişiye özel kupa","opis":"Adının yazılı olduğu SLFF kupası (en fazla 12 karakter)."},"uk":{"ime":"Чашка з ім’ям","opis":"Чашка з гербом SLFF і твоїм ім’ям (до 12 символів)."}}$p$::jsonb where slug = 'skodelica-ime';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Mini-liqa çempionu futbolkası","opis":"Mini-liqa çempionu üçün futbolka: arxasında liqanın adı və mövsüm. Onu yalnız başa çatmış mövsümün qalib komandasının sahibi ala bilər."},"cs":{"ime":"Tričko šampiona miniligy","opis":"Tričko pro šampiona miniligy: na zádech název ligy a sezóna. Koupit ho může jen majitel vítězného týmu dokončené sezóny."},"da":{"ime":"T-shirt til miniligamesteren","opis":"T-shirt til mesteren i en miniliga: ligaens navn og sæsonen på ryggen. Den kan kun købes af ejeren af vinderholdet i en afsluttet sæson."},"de":{"ime":"Mini-Liga-Meister-T-Shirt","opis":"T-Shirt für den Meister einer Mini-Liga: auf dem Rücken Name der Liga und Saison. Kaufen kann es nur der Besitzer des Siegerteams einer abgeschlossenen Saison."},"el":{"ime":"Μπλουζάκι πρωταθλητή μίνι λίγκας","opis":"Μπλουζάκι για τον πρωταθλητή μίνι λίγκας, με το όνομα της λίγκας και τη σεζόν στην πλάτη. Μπορεί να το αγοράσει μόνο ο κάτοχος της ομάδας που κέρδισε μια ολοκληρωμένη σεζόν."},"es":{"ime":"Camiseta de campeón de miniliga","opis":"Camiseta para el campeón de una miniliga: en la espalda, el nombre de la liga y la temporada. Solo la puede comprar el propietario del equipo ganador de una temporada terminada."},"et":{"ime":"Miniliiga meistri T-särk","opis":"T-särk miniliiga meistrile: seljal liiga nimi ja hooaeg. Seda saab osta ainult lõppenud hooaja võitnud meeskonna omanik."},"hr":{"ime":"Majica prvaka mini lige","opis":"Majica za prvaka mini lige: na leđima ime lige i sezona. Može je kupiti samo vlasnik pobjedničke momčadi završene sezone."},"hu":{"ime":"Miniliga-bajnoki póló","opis":"Póló a miniliga bajnokának: a hátán a liga neve és a szezon. Csak a lezárt szezon győztes csapatának tulajdonosa veheti meg."},"hy":{"ime":"Մինի լիգայի չեմպիոնի շապիկ","opis":"Շապիկ մինի լիգայի չեմպիոնի համար. մեջքին՝ լիգայի անունը և մրցաշրջանը։ Այն կարող է գնել միայն ավարտված մրցաշրջանի հաղթող թիմի տերը։"},"lv":{"ime":"Minilīgas čempiona T-krekls","opis":"T-krekls minilīgas čempionam: uz muguras līgas nosaukums un sezona. To var iegādāties tikai pabeigtās sezonas uzvarētājas komandas īpašnieks."},"mk":{"ime":"Маица за шампион на мини лига","opis":"Маица за шампионот на мини лигата: на грбот името на лигата и сезоната. Може да ја купи само сопственикот на победничкиот тим од завршена сезона."},"pl":{"ime":"Koszulka mistrza miniligi","opis":"Koszulka dla mistrza miniligi: na plecach nazwa ligi i sezon. Może ją kupić tylko właściciel zwycięskiej drużyny zakończonego sezonu."},"ro":{"ime":"Tricou de campion de mini-ligă","opis":"Tricou pentru campionul unei mini-ligi: pe spate numele ligii și sezonul. Îl poate cumpăra doar proprietarul echipei câștigătoare a unui sezon încheiat."},"sk":{"ime":"Tričko šampióna mini ligy","opis":"Tričko pre šampióna mini ligy: na chrbte názov ligy a sezóna. Kúpiť ho môže len vlastník víťazného tímu ukončenej sezóny."},"sr":{"ime":"Majica šampiona mini lige","opis":"Majica za šampiona mini lige: na leđima ime lige i sezona. Može da je kupi samo vlasnik pobedničkog tima završene sezone."},"tr":{"ime":"Mini lig şampiyonu tişörtü","opis":"Mini lig şampiyonu için tişört; sırtında lig adı ve sezon. Yalnızca tamamlanmış bir sezonu kazanan takımın sahibi satın alabilir."},"uk":{"ime":"Футболка чемпіона міні-ліги","opis":"Футболка для чемпіона міні-ліги: на спині назва ліги й сезон. Купити її може лише власник команди-переможниці завершеного сезону."}}$p$::jsonb where slug = 'majica-prvak';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Çempion fincanı","opis":"Liqanın adı və mövsüm yazılmış mini-liqa çempionu fincanı. Yalnız qalib komandanın sahibi üçün."},"cs":{"ime":"Hrnek šampiona","opis":"Hrnek šampiona miniligy s názvem ligy a sezónou. Jen pro majitele vítězného týmu."},"da":{"ime":"Mesterkrus","opis":"Krus til miniligamesteren med ligaens navn og sæsonen. Kun til ejeren af vinderholdet."},"de":{"ime":"Meistertasse","opis":"Tasse für den Meister einer Mini-Liga mit Name der Liga und Saison. Nur für den Besitzer des Siegerteams."},"el":{"ime":"Κούπα πρωταθλητή","opis":"Κούπα πρωταθλητή μίνι λίγκας με το όνομα της λίγκας και τη σεζόν. Μόνο για τον κάτοχο της ομάδας που κέρδισε."},"es":{"ime":"Taza de campeón","opis":"Taza de campeón de miniliga con el nombre de la liga y la temporada. Solo para el propietario del equipo ganador."},"et":{"ime":"Meistri kruus","opis":"Miniliiga meistri kruus liiga nime ja hooajaga. Ainult võitnud meeskonna omanikule."},"hr":{"ime":"Šalica prvaka","opis":"Šalica prvaka mini lige s imenom lige i sezonom. Samo za vlasnika pobjedničke momčadi."},"hu":{"ime":"Bajnoki bögre","opis":"A miniliga bajnokának bögréje a liga nevével és a szezonnal. Csak a győztes csapat tulajdonosának."},"hy":{"ime":"Չեմպիոնի գավաթ","opis":"Մինի լիգայի չեմպիոնի գավաթ՝ լիգայի անունով և մրցաշրջանով։ Միայն հաղթող թիմի տիրոջ համար։"},"lv":{"ime":"Čempiona krūze","opis":"Minilīgas čempiona krūze ar līgas nosaukumu un sezonu. Tikai uzvarētājas komandas īpašniekam."},"mk":{"ime":"Шолја за шампион","opis":"Шолја за шампионот на мини лигата со името на лигата и сезоната. Само за сопственикот на победничкиот тим."},"pl":{"ime":"Kubek mistrza","opis":"Kubek mistrza miniligi z nazwą ligi i sezonem. Tylko dla właściciela zwycięskiej drużyny."},"ro":{"ime":"Cana campionului","opis":"Cana campionului de mini-ligă cu numele ligii și sezonul. Doar pentru proprietarul echipei câștigătoare."},"sk":{"ime":"Hrnček šampióna","opis":"Hrnček šampióna mini ligy s názvom ligy a sezónou. Len pre vlastníka víťazného tímu."},"sr":{"ime":"Šolja šampiona","opis":"Šolja šampiona mini lige sa imenom lige i sezonom. Samo za vlasnika pobedničkog tima."},"tr":{"ime":"Şampiyon kupası","opis":"Lig adı ve sezon yazılı mini lig şampiyonu kupası. Yalnızca kazanan takımın sahibi için."},"uk":{"ime":"Чашка чемпіона","opis":"Чашка чемпіона міні-ліги з назвою ліги й сезоном. Лише для власника команди-переможниці."}}$p$::jsonb where slug = 'skodelica-prvak';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Təsdiqlənmiş oyunçu nişanı","opis":"Profilindəki ad yazılmış çap olunmuş təsdiqlənmiş oyunçu nişanı. Ömürlük təsdiqlənmiş oyunçular üçün."},"cs":{"ime":"Odznak ověřeného hráče","opis":"Tištěný odznak ověřeného hráče se jménem z tvého profilu. Pro hráče s doživotním ověřením."},"da":{"ime":"Badge for verificeret spiller","opis":"Trykt badge for verificeret spiller med navnet fra din profil. Til spillere med verificering for altid."},"de":{"ime":"Abzeichen verifizierter Spieler","opis":"Gedrucktes Abzeichen für verifizierte Spieler mit dem Namen aus deinem Profil. Für Spieler mit Verifizierung für immer."},"el":{"ime":"Σήμα επαληθευμένου παίκτη","opis":"Τυπωμένο σήμα επαληθευμένου παίκτη με το όνομα από το προφίλ σου. Για παίκτες με ισόβια επαλήθευση."},"es":{"ime":"Insignia de jugador verificado","opis":"Insignia impresa de jugador verificado con el nombre de tu perfil. Para jugadores con verificación de por vida."},"et":{"ime":"Kinnitatud mängija märk","opis":"Trükitud kinnitatud mängija märk sinu profiilil oleva nimega. Eluaegse kinnitusega mängijatele."},"hr":{"ime":"Značka provjerenog igrača","opis":"Tiskana značka provjerenog igrača s imenom s tvojeg profila. Za igrače s doživotnom provjerom."},"hu":{"ime":"Ellenőrzött játékos jelvénye","opis":"Nyomtatott ellenőrzött játékos jelvény a profilodon szereplő névvel. Örökös ellenőrzéssel rendelkező játékosoknak."},"hy":{"ime":"Հաստատված խաղացողի կրծքանշան","opis":"Հաստատված խաղացողի տպված կրծքանշան՝ քո պրոֆիլի անունով։ Ընդմիշտ հաստատմամբ խաղացողների համար։"},"lv":{"ime":"Pārbaudīta spēlētāja nozīmīte","opis":"Drukāta pārbaudīta spēlētāja nozīmīte ar vārdu no tava profila. Spēlētājiem ar pārbaudi uz visiem laikiem."},"mk":{"ime":"Значка за проверен играч","opis":"Отпечатена значка за проверен играч со името од твојот профил. За играчи со доживотна проверка."},"pl":{"ime":"Odznaka zweryfikowanego zawodnika","opis":"Drukowana odznaka zweryfikowanego zawodnika z imieniem z twojego profilu. Dla zawodników z weryfikacją na zawsze."},"ro":{"ime":"Insignă de jucător verificat","opis":"Insignă tipărită de jucător verificat cu numele din profilul tău. Pentru jucătorii cu verificare pentru totdeauna."},"sk":{"ime":"Odznak overeného hráča","opis":"Vytlačený odznak overeného hráča s menom z tvojho profilu. Pre hráčov s doživotným overením."},"sr":{"ime":"Značka proverenog igrača","opis":"Štampana značka proverenog igrača sa imenom sa tvog profila. Za igrače sa doživotnom proverom."},"tr":{"ime":"Doğrulanmış oyuncu rozeti","opis":"Profilindeki adın yazılı olduğu basılı doğrulanmış oyuncu rozeti. Ömür boyu doğrulaması olan oyuncular için."},"uk":{"ime":"Значок підтвердженого гравця","opis":"Надрукований значок підтвердженого гравця з ім’ям із твого профілю. Для гравців із довічною верифікацією."}}$p$::jsonb where slug = 'znacka';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Hədiyyə kartı","opis":"SLFF mağazası üçün hədiyyə kartı. Kodu ödənişdən dərhal sonra e-poçtla göndəririk, bir il etibarlıdır."},"cs":{"ime":"Dárkový poukaz","opis":"Dárkový poukaz do obchodu SLFF. Kód pošleme e-mailem hned po zaplacení, platí jeden rok."},"da":{"ime":"Gavekort","opis":"Gavekort til SLFF Shop. Vi sender koden pr. e-mail lige efter betalingen, og den gælder i et år."},"de":{"ime":"Gutschein","opis":"Gutschein für den SLFF Shop. Den Code senden wir direkt nach der Zahlung per E-Mail, er gilt ein Jahr."},"el":{"ime":"Δωροκάρτα","opis":"Δωροκάρτα για το κατάστημα SLFF. Σου στέλνουμε τον κωδικό με email αμέσως μετά την πληρωμή· ισχύει έναν χρόνο."},"es":{"ime":"Tarjeta regalo","opis":"Tarjeta regalo para la tienda SLFF. Te enviamos el código por correo electrónico justo después del pago; es válida durante un año."},"et":{"ime":"Kinkekaart","opis":"Kinkekaart SLFF-i poodi. Saadame koodi e-postiga kohe pärast makset, see kehtib ühe aasta."},"hr":{"ime":"Poklon bon","opis":"Poklon bon za trgovinu SLFF. Kod šaljemo e-poštom odmah nakon plaćanja, vrijedi godinu dana."},"hu":{"ime":"Ajándékutalvány","opis":"Ajándékutalvány az SLFF boltba. A kódot a fizetés után azonnal e-mailben küldjük, egy évig érvényes."},"hy":{"ime":"Նվեր քարտ","opis":"Նվեր քարտ SLFF խանութի համար։ Կոդն ուղարկում ենք էլ. փոստով վճարումից անմիջապես հետո, այն գործում է մեկ տարի։"},"lv":{"ime":"Dāvanu karte","opis":"Dāvanu karte SLFF veikalam. Kodu nosūtām pa e-pastu uzreiz pēc apmaksas, tā ir derīga vienu gadu."},"mk":{"ime":"Подарок-ваучер","opis":"Подарок-ваучер за SLFF продавницата. Кодот го испраќаме по е-пошта веднаш по плаќањето, важи една година."},"pl":{"ime":"Bon podarunkowy","opis":"Bon podarunkowy do sklepu SLFF. Kod wysyłamy e-mailem zaraz po płatności, jest ważny rok."},"ro":{"ime":"Voucher cadou","opis":"Voucher cadou pentru magazinul SLFF. Trimitem codul prin e-mail imediat după plată, este valabil un an."},"sk":{"ime":"Darčeková poukážka","opis":"Darčeková poukážka do obchodu SLFF. Kód pošleme e-mailom hneď po zaplatení, platí jeden rok."},"sr":{"ime":"Poklon vaučer","opis":"Poklon vaučer za SLFF prodavnicu. Kod šaljemo imejlom odmah posle plaćanja, važi godinu dana."},"tr":{"ime":"Hediye çeki","opis":"SLFF mağazası için hediye çeki. Kodu ödemeden hemen sonra e-postayla göndeririz; bir yıl geçerlidir."},"uk":{"ime":"Подарунковий сертифікат","opis":"Подарунковий сертифікат для магазину SLFF. Код надсилаємо електронною поштою одразу після оплати, дійсний один рік."}}$p$::jsonb where slug = 'darilni-bon';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Ad və nömrəli hudi","opis":"SLFF gerbli kapüşonlu hudi, arxasında sənin adın (12 simvola qədər) və istəyə görə nömrə."},"cs":{"ime":"Mikina se jménem a číslem","opis":"Mikina s kapucí a erbem SLFF, na zádech tvoje jméno (až 12 znaků) a podle přání číslo."},"da":{"ime":"Hættetrøje med navn og nummer","opis":"Hættetrøje med SLFF-emblemet, dit navn (op til 12 tegn) på ryggen og et nummer, hvis du vil."},"de":{"ime":"Hoodie mit Name und Nummer","opis":"Kapuzenpullover mit SLFF-Wappen, auf dem Rücken dein Name (bis 12 Zeichen) und auf Wunsch eine Nummer."},"el":{"ime":"Φούτερ με όνομα και αριθμό","opis":"Φούτερ SLFF με το όνομά σου (έως 12 χαρακτήρες) και, αν θέλεις, αριθμό στην πλάτη."},"es":{"ime":"Sudadera con nombre y dorsal","opis":"Sudadera con capucha y el escudo de SLFF, con tu nombre (hasta 12 caracteres) y, si quieres, un dorsal en la espalda."},"et":{"ime":"Nime ja numbriga pusa","opis":"Kapuutsiga pusa SLFF-i embleemiga, seljal sinu nimi (kuni 12 tähemärki) ja soovi korral number."},"hr":{"ime":"Dukserica s imenom i brojem","opis":"Dukserica s kapuljačom i grbom SLFF, na leđima tvoje ime (do 12 znakova) i po želji broj."},"hu":{"ime":"Pulóver névvel és számmal","opis":"Kapucnis pulóver SLFF címerrel, a hátán a neved (legfeljebb 12 karakter) és kérésre egy szám."},"hy":{"ime":"Հուդի անունով և համարով","opis":"Հուդի՝ SLFF զինանշանով, մեջքին՝ քո անունը (մինչև 12 նիշ) և ցանկության դեպքում՝ համար։"},"lv":{"ime":"Džemperis ar vārdu un numuru","opis":"Džemperis ar kapuci un SLFF ģerboni, uz muguras tavs vārds (līdz 12 rakstzīmēm) un pēc vēlēšanās numurs."},"mk":{"ime":"Дуксер со име и број","opis":"Дуксер со качулка и грбот на SLFF, на грбот твоето име (до 12 знаци) и по желба број."},"pl":{"ime":"Bluza z imieniem i numerem","opis":"Bluza z kapturem i herbem SLFF, na plecach twoje imię (do 12 znaków) i opcjonalnie numer."},"ro":{"ime":"Hanorac cu nume și număr","opis":"Hanorac cu glugă și emblema SLFF, pe spate numele tău (până la 12 caractere) și, dacă vrei, un număr."},"sk":{"ime":"Mikina s menom a číslom","opis":"Mikina s kapucňou a erbom SLFF, na chrbte tvoje meno (do 12 znakov) a podľa želania číslo."},"sr":{"ime":"Duks sa imenom i brojem","opis":"Duks sa kapuljačom i SLFF grbom, na leđima tvoje ime (do 12 znakova) i po želji broj."},"tr":{"ime":"İsim ve numaralı sweatshirt","opis":"Sırtında adın (en fazla 12 karakter) ve isteğe bağlı numara olan SLFF kapüşonlu sweatshirt."},"uk":{"ime":"Худі з ім’ям і номером","opis":"Худі з капюшоном і гербом SLFF, на спині твоє ім’я (до 12 символів) і за бажанням номер."}}$p$::jsonb where slug = 'pulover-ime-stevilka';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Komanda adı yazılmış şərf","opis":"Fantasy komandanın adı yazılmış SLFF azarkeş şərfi."},"cs":{"ime":"Šála s názvem týmu","opis":"Fanouškovská šála SLFF s názvem tvého fantasy týmu."},"da":{"ime":"Halstørklæde med holdnavn","opis":"SLFF-fanhalstørklæde med dit fantasyholds navn."},"de":{"ime":"Schal mit Teamnamen","opis":"SLFF-Fanschal mit dem Namen deines Fantasy-Teams."},"el":{"ime":"Κασκόλ fantasy ομάδας","opis":"Κασκόλ οπαδού SLFF με το όνομα της fantasy ομάδας σου."},"es":{"ime":"Bufanda con el nombre del equipo","opis":"Bufanda de aficionado SLFF con el nombre de tu equipo fantasy."},"et":{"ime":"Meeskonna nimega sall","opis":"SLFF-i fännisall sinu fantaasiameeskonna nimega."},"hr":{"ime":"Šal s imenom momčadi","opis":"Navijački šal SLFF s imenom tvoje fantasy momčadi."},"hu":{"ime":"Sál a csapat nevével","opis":"SLFF szurkolói sál a fantasy csapatod nevével."},"hy":{"ime":"Շարֆ թիմի անունով","opis":"SLFF երկրպագուի շարֆ՝ քո ֆենթեզի թիմի անունով։"},"lv":{"ime":"Šalle ar komandas nosaukumu","opis":"SLFF līdzjutēju šalle ar tavas fantasy komandas nosaukumu."},"mk":{"ime":"Шал со име на тимот","opis":"Навивачки SLFF шал со името на твојот фантази тим."},"pl":{"ime":"Szalik z nazwą drużyny","opis":"Szalik kibica SLFF z nazwą twojej drużyny fantasy."},"ro":{"ime":"Fular cu numele echipei","opis":"Fular de suporter SLFF cu numele echipei tale fantasy."},"sk":{"ime":"Šál s názvom tímu","opis":"Fanúšikovský šál SLFF s názvom tvojho fantasy tímu."},"sr":{"ime":"Šal sa imenom tima","opis":"SLFF navijački šal sa imenom tvog fantasy tima."},"tr":{"ime":"Fantezi takım atkısı","opis":"Fantezi takımının adı yazılı SLFF taraftar atkısı."},"uk":{"ime":"Шарф із назвою команди","opis":"Фанатський шарф SLFF з назвою твоєї фентезі-команди."}}$p$::jsonb where slug = 'sal-ime-ekipe';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Adlı pivə stəkanı","opis":"SLFF gerbi və sənin adın (12 simvola qədər) olan 0,5 l pivə stəkanı."},"cs":{"ime":"Pivní sklenice se jménem","opis":"Pivní sklenice 0,5 l s erbem SLFF a tvým jménem (až 12 znaků)."},"da":{"ime":"Ølglas med navn","opis":"Ølglas på 0,5 l med SLFF-emblemet og dit navn (op til 12 tegn)."},"de":{"ime":"Bierglas mit Namen","opis":"Bierglas 0,5 l mit SLFF-Wappen und deinem Namen (bis 12 Zeichen)."},"el":{"ime":"Ποτήρι μπίρας με όνομα","opis":"Ποτήρι μπίρας SLFF 0,5 l με το όνομά σου (έως 12 χαρακτήρες)."},"es":{"ime":"Vaso de cerveza con nombre","opis":"Vaso de cerveza de 0,5 l con el escudo de SLFF y tu nombre (hasta 12 caracteres)."},"et":{"ime":"Nimega õlleklaas","opis":"Õlleklaas 0,5 l SLFF-i embleemi ja sinu nimega (kuni 12 tähemärki)."},"hr":{"ime":"Pivska čaša s imenom","opis":"Pivska čaša od 0,5 l s grbom SLFF i tvojim imenom (do 12 znakova)."},"hu":{"ime":"Söröspohár névvel","opis":"0,5 literes söröspohár SLFF címerrel és a neveddel (legfeljebb 12 karakter)."},"hy":{"ime":"Գարեջրի բաժակ անունով","opis":"Գարեջրի բաժակ 0,5 լ՝ SLFF զինանշանով և քո անունով (մինչև 12 նիշ)։"},"lv":{"ime":"Alus glāze ar vārdu","opis":"Alus glāze 0,5 l ar SLFF ģerboni un tavu vārdu (līdz 12 rakstzīmēm)."},"mk":{"ime":"Чаша за пиво со име","opis":"Чаша за пиво од 0,5 l со грбот на SLFF и твоето име (до 12 знаци)."},"pl":{"ime":"Szklanka do piwa z imieniem","opis":"Szklanka do piwa 0,5 l z herbem SLFF i twoim imieniem (do 12 znaków)."},"ro":{"ime":"Halbă de bere cu nume","opis":"Pahar de bere de 0,5 l cu emblema SLFF și numele tău (până la 12 caractere)."},"sk":{"ime":"Pivový pohár s menom","opis":"Pivový pohár 0,5 l s erbom SLFF a tvojím menom (do 12 znakov)."},"sr":{"ime":"Čaša za pivo sa imenom","opis":"Čaša za pivo od 0,5 l sa SLFF grbom i tvojim imenom (do 12 znakova)."},"tr":{"ime":"Kişiye özel bira bardağı","opis":"Adının yazılı olduğu 0,5 l SLFF bira bardağı (en fazla 12 karakter)."},"uk":{"ime":"Пивний келих з ім’ям","opis":"Пивний келих 0,5 л з гербом SLFF і твоїм ім’ям (до 12 символів)."}}$p$::jsonb where slug = 'kozarec-ime';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Komandanın stikerləri","opis":"SLFF gerbi və fantasy komandanın adı olan stiker dəsti. Məktubla göndəririk."},"cs":{"ime":"Samolepky tvého týmu","opis":"Sada samolepek s erbem SLFF a názvem tvého fantasy týmu. Posíláme dopisem."},"da":{"ime":"Dit holds klistermærker","opis":"Sæt klistermærker med SLFF-emblemet og dit fantasyholds navn. Sendes som brev."},"de":{"ime":"Sticker deines Teams","opis":"Stickerset mit SLFF-Wappen und dem Namen deines Fantasy-Teams. Versand als Brief."},"el":{"ime":"Αυτοκόλλητα της ομάδας σου","opis":"Σετ αυτοκόλλητων με το έμβλημα του SLFF και το όνομα της fantasy ομάδας σου. Αποστέλλεται ως επιστολή."},"es":{"ime":"Pegatinas de tu equipo","opis":"Juego de pegatinas con el escudo de SLFF y el nombre de tu equipo fantasy. Se envían por carta."},"et":{"ime":"Sinu meeskonna kleebised","opis":"Kleebiste komplekt SLFF-i embleemi ja sinu fantaasiameeskonna nimega. Saadame kirjaga."},"hr":{"ime":"Naljepnice tvoje momčadi","opis":"Komplet naljepnica s grbom SLFF i imenom tvoje fantasy momčadi. Šaljemo pismom."},"hu":{"ime":"A csapatod matricái","opis":"Matricakészlet SLFF címerrel és a fantasy csapatod nevével. Levélként küldjük."},"hy":{"ime":"Քո թիմի կպչուն պիտակները","opis":"Կպչուն պիտակների հավաքածու՝ SLFF զինանշանով և քո ֆենթեզի թիմի անունով։ Ուղարկում ենք նամակով։"},"lv":{"ime":"Tavas komandas uzlīmes","opis":"Uzlīmju komplekts ar SLFF ģerboni un tavas fantasy komandas nosaukumu. Sūtām vēstulē."},"mk":{"ime":"Налепници на твојот тим","opis":"Комплет налепници со грбот на SLFF и името на твојот фантази тим. Ги испраќаме со писмо."},"pl":{"ime":"Naklejki twojej drużyny","opis":"Zestaw naklejek z herbem SLFF i nazwą twojej drużyny fantasy. Wysyłamy listem."},"ro":{"ime":"Autocolantele echipei tale","opis":"Set de autocolante cu emblema SLFF și numele echipei tale fantasy. Le trimitem prin scrisoare."},"sk":{"ime":"Nálepky tvojho tímu","opis":"Sada nálepiek s erbom SLFF a názvom tvojho fantasy tímu. Posielame listom."},"sr":{"ime":"Nalepnice tvog tima","opis":"Komplet nalepnica sa SLFF grbom i imenom tvog fantasy tima. Šaljemo pismom."},"tr":{"ime":"Takımına özel çıkartma seti","opis":"SLFF arması ve fantezi takımının adı olan çıkartma seti. Mektupla gönderilir."},"uk":{"ime":"Наліпки твоєї команди","opis":"Набір наліпок з гербом SLFF і назвою твоєї фентезі-команди. Надсилаємо листом."}}$p$::jsonb where slug = 'nalepke-ekipa';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Fərdi futbolka","opis":"Pambıq futbolka, 180 q, sənin istədiyin kimi bazar liqası dizaynı ilə. Dizaynı seç, öz mətnini yaz və necə görünəcəyinə bax."},"cs":{"ime":"Tričko na míru","opis":"Bavlněné tričko, 180 g, s motivem nedělní ligy po tvém. Vyber motiv, napiš své a podívej se, jak bude vypadat."},"da":{"ime":"T-shirt med eget design","opis":"T-shirt i bomuld, 180 g, med et søndagsligamotiv, som du vil have det. Vælg et motiv, skriv dit eget, og se, hvordan det bliver."},"de":{"ime":"Individuelles T-Shirt","opis":"Baumwoll-T-Shirt, 180 g, mit einem Sonntagsliga-Motiv nach deinem Geschmack. Wähl ein Motiv, trag deins ein und sieh, wie es aussieht."},"el":{"ime":"Μπλουζάκι με εξατομίκευση","opis":"Βαμβακερό μπλουζάκι 180 g με σχέδιο του κυριακάτικου πρωταθλήματος όπως το θέλεις. Διάλεξε σχέδιο, συμπλήρωσέ το και δες πώς φαίνεται."},"es":{"ime":"Camiseta personalizada","opis":"Camiseta de algodón, 180 g, con un diseño de liga de domingo a tu manera. Elige un diseño, escribe lo tuyo y mira cómo queda."},"et":{"ime":"Personaalne T-särk","opis":"Puuvillane T-särk, 180 g, sinu enda pühapäevaliiga kujundusega. Vali kujundus, kirjuta oma tekst ja vaata, milline see välja näeb."},"hr":{"ime":"Majica po mjeri","opis":"Pamučna majica, 180 g, s motivom nedjeljne lige po tvom. Odaberi motiv, upiši svoje i pogledaj kako će izgledati."},"hu":{"ime":"Egyedi póló","opis":"Pamutpóló, 180 g, a saját ízlésed szerinti vasárnapi bajnokságos mintával. Válassz mintát, írd be a sajátod, és nézd meg, hogyan fog kinézni."},"hy":{"ime":"Անհատական շապիկ","opis":"Բամբակյա շապիկ, 180 գ, կիրակնօրյա լիգայի դիզայնով՝ քո ձևով։ Ընտրիր դիզայնը, լրացրու քոնը և տես, թե ինչ տեսք կունենա։"},"lv":{"ime":"T-krekls ar savu dizainu","opis":"Kokvilnas T-krekls, 180 g, ar svētdienas līgas dizainu pēc tava prāta. Izvēlies dizainu, ieraksti savu un apskati, kā tas izskatīsies."},"mk":{"ime":"Маица по мерка","opis":"Памучна маица, 180 g, со мотив од неделната лига по твое. Избери мотив, внеси свое и погледни како ќе изгледа."},"pl":{"ime":"Koszulka z własnym wzorem","opis":"Bawełniana koszulka, 180 g, ze wzorem niedzielnej ligi po twojemu. Wybierz wzór, wpisz swoje i zobacz, jak będzie wyglądać."},"ro":{"ime":"Tricou personalizat","opis":"Tricou din bumbac, 180 g, cu un model de ligă de duminică după gustul tău. Alege modelul, scrie ce vrei și vezi cum va arăta."},"sk":{"ime":"Tričko na mieru","opis":"Bavlnené tričko, 180 g, s motívom nedeľnej ligy po tvojom. Vyber motív, napíš svoje a pozri sa, ako bude vyzerať."},"sr":{"ime":"Majica po meri","opis":"Pamučna majica, 180 g, sa motivom nedeljne lige po tvom. Izaberi motiv, upiši svoje i pogledaj kako će izgledati."},"tr":{"ime":"Kişiye özel tişört","opis":"Pamuklu tişört, 180 g, kendi yorumunla bir pazar ligi tasarımı. Bir tasarım seç, doldur ve nasıl göründüğüne bak."},"uk":{"ime":"Футболка на замовлення","opis":"Бавовняна футболка, 180 г, з дизайном недільної ліги на твій смак. Обери дизайн, впиши своє і подивися, який вигляд він матиме."}}$p$::jsonb where slug = 'majica-po-meri';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Fərdi hudi","opis":"İsti kapüşonlu hudi, 550 q, sənin istədiyin kimi bazar liqası dizaynı ilə. Meydança kənarında soyuq oyunlar üçün."},"cs":{"ime":"Mikina na míru","opis":"Teplá mikina s kapucí, 550 g, s motivem nedělní ligy po tvém. Na chladné zápasy u hřiště."},"da":{"ime":"Hættetrøje med eget design","opis":"Varm hættetrøje, 550 g, med et søndagsligamotiv, som du vil have det. Til kolde kampe ved sidelinjen."},"de":{"ime":"Individueller Hoodie","opis":"Warmer Kapuzenpullover, 550 g, mit einem Sonntagsliga-Motiv nach deinem Geschmack. Für kalte Spiele am Spielfeldrand."},"el":{"ime":"Φούτερ με εξατομίκευση","opis":"Ζεστό φούτερ 550 g με σχέδιο του κυριακάτικου πρωταθλήματος όπως το θέλεις. Για τους κρύους αγώνες δίπλα στο γήπεδο."},"es":{"ime":"Sudadera personalizada","opis":"Sudadera con capucha calentita, 550 g, con un diseño de liga de domingo a tu manera. Para los partidos con frío a pie de campo."},"et":{"ime":"Personaalne pusa","opis":"Soe kapuutsiga pusa, 550 g, sinu enda pühapäevaliiga kujundusega. Külmadeks mängudeks väljaku ääres."},"hr":{"ime":"Dukserica po mjeri","opis":"Topla dukserica s kapuljačom, 550 g, s motivom nedjeljne lige po tvom. Za hladne utakmice uz teren."},"hu":{"ime":"Egyedi pulóver","opis":"Meleg kapucnis pulóver, 550 g, a saját ízlésed szerinti vasárnapi bajnokságos mintával. Hideg meccsekre a pálya szélén."},"hy":{"ime":"Անհատական հուդի","opis":"Տաք հուդի, 550 գ, կիրակնօրյա լիգայի դիզայնով՝ քո ձևով։ Դաշտի եզրին ցուրտ խաղերի համար։"},"lv":{"ime":"Džemperis ar savu dizainu","opis":"Silts džemperis ar kapuci, 550 g, ar svētdienas līgas dizainu pēc tava prāta. Aukstām spēlēm pie laukuma."},"mk":{"ime":"Дуксер по мерка","opis":"Топол дуксер со качулка, 550 g, со мотив од неделната лига по твое. За студените натпревари покрај теренот."},"pl":{"ime":"Bluza z własnym wzorem","opis":"Ciepła bluza z kapturem, 550 g, ze wzorem niedzielnej ligi po twojemu. Na chłodne mecze przy boisku."},"ro":{"ime":"Hanorac personalizat","opis":"Hanorac călduros cu glugă, 550 g, cu un model de ligă de duminică după gustul tău. Pentru meciurile reci de lângă teren."},"sk":{"ime":"Mikina na mieru","opis":"Teplá mikina s kapucňou, 550 g, s motívom nedeľnej ligy po tvojom. Na chladné zápasy pri ihrisku."},"sr":{"ime":"Duks po meri","opis":"Topao duks sa kapuljačom, 550 g, sa motivom nedeljne lige po tvom. Za hladne utakmice pored terena."},"tr":{"ime":"Kişiye özel sweatshirt","opis":"Sıcak kapüşonlu sweatshirt, 550 g, kendi yorumunla bir pazar ligi tasarımı. Saha kenarındaki soğuk maçlar için."},"uk":{"ime":"Худі на замовлення","opis":"Тепле худі з капюшоном, 550 г, з дизайном недільної ліги на твій смак. Для холодних матчів біля поля."}}$p$::jsonb where slug = 'pulover-po-meri';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Fərdi pivə stəkanı","opis":"Yuyulub getməyən lazer qravürası olan 0,5 l pivə stəkanı. İlk ikisindən uzun çəkən üçüncü hissə üçün."},"cs":{"ime":"Pivní sklenice na míru","opis":"Pivní sklenice 0,5 l s laserovou gravurou, která se nesmyje. Na třetí poločas, který trvá déle než první dva."},"da":{"ime":"Ølglas med eget design","opis":"Ølglas på 0,5 l med lasergravering, der ikke kan vaskes af. Til tredje halvleg, der varer længere end de to første."},"de":{"ime":"Individuelles Bierglas","opis":"Bierglas 0,5 l mit Lasergravur, die nicht abgeht. Für die dritte Halbzeit, die länger dauert als die ersten beiden."},"el":{"ime":"Ποτήρι μπίρας με εξατομίκευση","opis":"Ποτήρι μπίρας 0,5 l με χάραξη λέιζερ που δεν φεύγει ποτέ στο πλύσιμο. Για το τρίτο ημίχρονο που κρατάει περισσότερο από τα δύο πρώτα."},"es":{"ime":"Vaso de cerveza personalizado","opis":"Vaso de cerveza de 0,5 l con grabado láser que no se va con los lavados. Para el tercer tiempo, que dura más que los dos primeros."},"et":{"ime":"Personaalne õlleklaas","opis":"Õlleklaas 0,5 l lasergraveeringuga, mis maha ei pese. Kolmanda poolaja jaoks, mis kestab kauem kui kaks esimest."},"hr":{"ime":"Pivska čaša po mjeri","opis":"Pivska čaša od 0,5 l s laserskom gravurom koja se ne ispire. Za treće poluvrijeme koje traje dulje od prva dva."},"hu":{"ime":"Egyedi söröspohár","opis":"0,5 literes söröspohár lézergravírozással, amely nem kopik le. A harmadik félidőre, amely tovább tart, mint az első kettő."},"hy":{"ime":"Անհատական գարեջրի բաժակ","opis":"Գարեջրի բաժակ 0,5 լ՝ լազերային փորագրությամբ, որը չի լվացվում։ Երրորդ խաղակեսի համար, որը տևում է ավելի երկար, քան առաջին երկուսը։"},"lv":{"ime":"Alus glāze ar savu dizainu","opis":"Alus glāze 0,5 l ar lāzergravējumu, kas nenomazgājas. Trešajam puslaikam, kas ilgst ilgāk par pirmajiem diviem."},"mk":{"ime":"Чаша за пиво по мерка","opis":"Чаша за пиво од 0,5 l со ласерска гравура што не се мие. За третото полувреме, кое трае подолго од првите две."},"pl":{"ime":"Szklanka do piwa z własnym wzorem","opis":"Szklanka do piwa 0,5 l z grawerem laserowym, który się nie zmywa. Na trzecią połowę, która trwa dłużej niż dwie pierwsze."},"ro":{"ime":"Halbă de bere personalizată","opis":"Pahar de bere de 0,5 l cu gravură laser care nu se spală. Pentru repriza a treia, care durează mai mult decât primele două."},"sk":{"ime":"Pivový pohár na mieru","opis":"Pivový pohár 0,5 l s laserovou gravúrou, ktorá sa nezmyje. Na tretí polčas, ktorý trvá dlhšie ako prvé dva."},"sr":{"ime":"Čaša za pivo po meri","opis":"Čaša za pivo od 0,5 l sa laserskom gravurom koja se ne spira. Za treće poluvreme koje traje duže od prva dva."},"tr":{"ime":"Kişiye özel bira bardağı","opis":"Asla silinmeyen lazer gravürlü 0,5 l bira bardağı. İlk iki devreden uzun süren üçüncü devre için."},"uk":{"ime":"Пивний келих на замовлення","opis":"Пивний келих 0,5 л з лазерним гравіюванням, яке не змивається. Для третього тайму, що триває довше за перші два."}}$p$::jsonb where slug = 'kozarec-po-meri';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Fərdi pivə krujkası","opis":"Dəstəkli şüşə krujka, 0,5 l, dövrəvi qravüra ilə. Komanda badə qaldıranda kimin olduğu görünür."},"cs":{"ime":"Pivní korbel na míru","opis":"Skleněný korbel s uchem, 0,5 l, gravura dokola. Když si tým připíjí, je vidět, čí je."},"da":{"ime":"Ølkrus med eget design","opis":"Ølkrus i glas med hank, 0,5 l, graveret hele vejen rundt. Når holdet skåler, kan alle se, hvis det er."},"de":{"ime":"Individueller Bierkrug","opis":"Glaskrug mit Henkel, 0,5 l, rundum graviert. Wenn das Team anstößt, sieht jeder, wem er gehört."},"el":{"ime":"Κούπα μπίρας με εξατομίκευση","opis":"Γυάλινη κούπα μπίρας 0,5 l με χερούλι, χαραγμένη γύρω γύρω. Όταν η ομάδα τσουγκρίζει, όλοι βλέπουν ποιανού είναι."},"es":{"ime":"Jarra de cerveza personalizada","opis":"Jarra de cristal con asa, 0,5 l, grabada alrededor. Cuando el equipo brinda, se ve de quién es."},"et":{"ime":"Personaalne õllekann","opis":"Sangaga klaaskann, 0,5 l, graveering ümberringi. Kui meeskond terviseks tõstab, on näha, kelle oma see on."},"hr":{"ime":"Pivski krigl po mjeri","opis":"Stakleni krigl s drškom, 0,5 l, gravura uokolo. Kad ekipa nazdravi, vidi se čiji je."},"hu":{"ime":"Egyedi söröskorsó","opis":"Füles üvegkorsó, 0,5 l, körbefutó gravírozással. Amikor a csapat koccint, látszik, kié."},"hy":{"ime":"Անհատական գարեջրի կրուժկա","opis":"Ապակե կրուժկա՝ բռնակով, 0,5 լ, փորագրությունը՝ շուրջբոլորը։ Երբ թիմը կենաց է խմում, երևում է, թե ումն է։"},"lv":{"ime":"Alus kauss ar savu dizainu","opis":"Stikla kauss ar rokturi, 0,5 l, gravējums visapkārt. Kad komanda saskandina, redzams, kura tas ir."},"mk":{"ime":"Кригла по мерка","opis":"Стаклена кригла со рачка, 0,5 l, гравура наоколу. Кога тимот ќе наздрави, се гледа чија е."},"pl":{"ime":"Kufel z własnym wzorem","opis":"Szklany kufel z uchem, 0,5 l, grawer dookoła. Kiedy drużyna wznosi toast, widać, czyj jest."},"ro":{"ime":"Halbă cu toartă personalizată","opis":"Halbă de sticlă cu toartă, 0,5 l, gravată de jur împrejur. Când echipa ciocnește, se vede a cui este."},"sk":{"ime":"Pivový krígeľ na mieru","opis":"Sklenený krígeľ s uchom, 0,5 l, gravúra dookola. Keď si tím pripíja, vidno, čí je."},"sr":{"ime":"Krigla po meri","opis":"Staklena krigla sa drškom, 0,5 l, gravura svuda okolo. Kad ekipa nazdravi, vidi se čija je."},"tr":{"ime":"Kişiye özel bira kupası","opis":"Her yanı gravürlü, kulplu 0,5 l cam kupa. Takım kadeh kaldırdığında herkes kimin olduğunu görür."},"uk":{"ime":"Пивний кухоль на замовлення","opis":"Скляний кухоль із ручкою, 0,5 л, гравіювання по колу. Коли команда піднімає тост, усі бачать, чий він."}}$p$::jsonb where slug = 'vrc-po-meri';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Fərdi altlıqlar ×6","opis":"Komanda adı və altı şüar olan altı altlıq dəsti — hər raund üçün ayrısı."},"cs":{"ime":"Podtácky na míru ×6","opis":"Sada šesti podtácků s názvem týmu a šesti slogany — na každou rundu jiný."},"da":{"ime":"Ølbrikker med eget design ×6","opis":"Sæt med seks ølbrikker med holdnavn og seks slogans — en til hver omgang."},"de":{"ime":"Individuelle Bierdeckel ×6","opis":"Set aus sechs Bierdeckeln mit Teamnamen und sechs Sprüchen — für jede Runde ein eigener."},"el":{"ime":"Σουβέρ με εξατομίκευση ×6","opis":"Σετ έξι σουβέρ με το όνομα της ομάδας σου και έξι συνθήματα — διαφορετικό για κάθε γύρο."},"es":{"ime":"Posavasos personalizados ×6","opis":"Juego de seis posavasos con el nombre del equipo y seis lemas: uno distinto para cada ronda."},"et":{"ime":"Personaalsed klaasialused ×6","opis":"Kuuest klaasialusest komplekt meeskonna nime ja kuue loosungiga — igale ringile oma."},"hr":{"ime":"Podmetači po mjeri ×6","opis":"Komplet od šest podmetača s imenom ekipe i šest slogana — za svaku rundu drugi."},"hu":{"ime":"Egyedi poháralátétek ×6","opis":"Hat poháralátét a csapat nevével és hat szlogennel — minden körre másik."},"hy":{"ime":"Անհատական տակդիրներ ×6","opis":"Վեց տակդիրների հավաքածու՝ թիմի անունով և վեց կարգախոսով. յուրաքանչյուր կենացի համար՝ իրենը։"},"lv":{"ime":"Paliktņi ar savu dizainu ×6","opis":"Sešu paliktņu komplekts ar komandas nosaukumu un sešiem saukļiem — katrai kārtai savs."},"mk":{"ime":"Подметнувачи по мерка ×6","opis":"Комплет од шест подметнувачи со името на тимот и шест слогани — за секоја тура по еден."},"pl":{"ime":"Podkładki z własnym wzorem ×6","opis":"Zestaw sześciu podkładek z nazwą drużyny i sześcioma hasłami — na każdą kolejkę inne."},"ro":{"ime":"Suporturi de pahar personalizate ×6","opis":"Set de șase suporturi de pahar cu numele echipei și șase sloganuri — pentru fiecare tură altul."},"sk":{"ime":"Podtácky na mieru ×6","opis":"Sada šiestich podtácok s názvom tímu a šiestimi sloganmi — na každú rundu iný."},"sr":{"ime":"Podmetači po meri ×6","opis":"Komplet od šest podmetača sa imenom ekipe i šest slogana — za svaku rundu drugi."},"tr":{"ime":"Kişiye özel bardak altlığı ×6","opis":"Takımının adı ve altı sloganla altı bardak altlığından oluşan set: her tura başka bir tane."},"uk":{"ime":"Підставки на замовлення ×6","opis":"Набір із шести підставок з назвою команди та шістьма гаслами — для кожного раунду своє."}}$p$::jsonb where slug = 'podstavki-po-meri';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Fərdi açacaq","opis":"Ad və nömrə qravürası olan metal açacaq. Oyundan sonra ən vacib alət."},"cs":{"ime":"Otvírák na míru","opis":"Kovový otvírák s gravurou jména a čísla. Nejdůležitější vybavení po zápase."},"da":{"ime":"Oplukker med eget design","opis":"Oplukker i metal med graveret navn og nummer. Det vigtigste stykke udstyr efter kampen."},"de":{"ime":"Individueller Flaschenöffner","opis":"Flaschenöffner aus Metall mit eingraviertem Namen und Nummer. Das wichtigste Utensil nach dem Abpfiff."},"el":{"ime":"Ανοιχτήρι με εξατομίκευση","opis":"Μεταλλικό ανοιχτήρι μπουκαλιών με χαραγμένο όνομα και αριθμό. Ο πιο σημαντικός εξοπλισμός μετά το τελικό σφύριγμα."},"es":{"ime":"Abridor personalizado","opis":"Abridor de metal con nombre y dorsal grabados. El accesorio más importante después del partido."},"et":{"ime":"Personaalne pudeliavaja","opis":"Metallist pudeliavaja nime ja numbri graveeringuga. Kõige tähtsam varustus pärast mängu."},"hr":{"ime":"Otvarač po mjeri","opis":"Metalni otvarač s gravurom imena i broja. Najvažnija oprema nakon utakmice."},"hu":{"ime":"Egyedi sörnyitó","opis":"Fém sörnyitó névvel és számmal gravírozva. A legfontosabb kellék a meccs után."},"hy":{"ime":"Անհատական շշաբացիչ","opis":"Մետաղական շշաբացիչ՝ անվան և համարի փորագրությամբ։ Խաղից հետո ամենակարևոր պարագան։"},"lv":{"ime":"Pudeļu attaisāmais ar savu dizainu","opis":"Metāla pudeļu attaisāmais ar iegravētu vārdu un numuru. Svarīgākais rīks pēc spēles."},"mk":{"ime":"Отворач по мерка","opis":"Метален отворач со гравирано име и број. Најважната опрема по натпреварот."},"pl":{"ime":"Otwieracz z własnym wzorem","opis":"Metalowy otwieracz z grawerem imienia i numeru. Najważniejszy sprzęt po meczu."},"ro":{"ime":"Desfăcător personalizat","opis":"Desfăcător de metal cu numele și numărul gravate. Cel mai important accesoriu după meci."},"sk":{"ime":"Otvárač na mieru","opis":"Kovový otvárač s gravúrou mena a čísla. Najdôležitejšia výbava po zápase."},"sr":{"ime":"Otvarač po meri","opis":"Metalni otvarač sa gravurom imena i broja. Najvažnija oprema posle utakmice."},"tr":{"ime":"Kişiye özel şişe açacağı","opis":"İsim ve numara kazınmış metal şişe açacağı. Son düdükten sonraki en önemli malzeme."},"uk":{"ime":"Відкривачка на замовлення","opis":"Металева відкривачка з гравіюванням імені та номера. Найважливіше спорядження після матчу."}}$p$::jsonb where slug = 'odpirac-po-meri';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Fərdi plakat","opis":"Qalın mat kağız üzərində plakat, A3 və ya A2. Soyunma otağının, otağın və ya ofisin divarı üçün."},"cs":{"ime":"Plakát na míru","opis":"Plakát na silném matném papíře, A3 nebo A2. Na zeď v šatně, pokoji nebo kanceláři."},"da":{"ime":"Plakat med eget design","opis":"Plakat på kraftigt mat papir, A3 eller A2. Til væggen i omklædningsrummet, på værelset eller på kontoret."},"de":{"ime":"Individuelles Poster","opis":"Poster auf dickem Mattpapier, A3 oder A2. Für die Wand in der Kabine, im Zimmer oder im Büro."},"el":{"ime":"Αφίσα με εξατομίκευση","opis":"Αφίσα σε χοντρό ματ χαρτί, A3 ή A2. Για τον τοίχο στα αποδυτήρια, στο υπνοδωμάτιο ή στο γραφείο."},"es":{"ime":"Póster personalizado","opis":"Póster en papel mate grueso, A3 o A2. Para la pared del vestuario, la habitación o la oficina."},"et":{"ime":"Personaalne plakat","opis":"Plakat paksul matil paberil, A3 või A2. Riietusruumi, toa või kontori seinale."},"hr":{"ime":"Plakat po mjeri","opis":"Plakat na debelom mat papiru, A3 ili A2. Za zid u svlačionici, sobi ili uredu."},"hu":{"ime":"Egyedi plakát","opis":"Plakát vastag matt papíron, A3 vagy A2 méretben. Az öltöző, a szoba vagy az iroda falára."},"hy":{"ime":"Անհատական պաստառ","opis":"Պաստառ հաստ փայլատ թղթի վրա, A3 կամ A2։ Հանդերձարանի, սենյակի կամ գրասենյակի պատի համար։"},"lv":{"ime":"Plakāts ar savu dizainu","opis":"Plakāts uz bieza matēta papīra, A3 vai A2. Sienai ģērbtuvē, istabā vai birojā."},"mk":{"ime":"Постер по мерка","opis":"Постер на дебела мат хартија, A3 или A2. За ѕидот во соблекувалната, собата или канцеларијата."},"pl":{"ime":"Plakat z własnym wzorem","opis":"Plakat na grubym matowym papierze, A3 lub A2. Na ścianę w szatni, pokoju albo biurze."},"ro":{"ime":"Poster personalizat","opis":"Poster pe hârtie mată groasă, A3 sau A2. Pentru peretele din vestiar, din cameră sau din birou."},"sk":{"ime":"Plagát na mieru","opis":"Plagát na hrubom matnom papieri, A3 alebo A2. Na stenu v šatni, izbe alebo kancelárii."},"sr":{"ime":"Poster po meri","opis":"Poster na debelom mat papiru, A3 ili A2. Za zid u svlačionici, sobi ili kancelariji."},"tr":{"ime":"Kişiye özel poster","opis":"Kalın mat kâğıda poster, A3 veya A2. Soyunma odası, yatak odası ya da ofis duvarı için."},"uk":{"ime":"Постер на замовлення","opis":"Постер на щільному матовому папері, A3 або A2. Для стіни в роздягальні, кімнаті чи офісі."}}$p$::jsonb where slug = 'plakat-po-meri';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Oyunçu kartı","opis":"Stiker albomundakı kimi böyük A5 kart, öz reytinqlərinlə. Reytinqləri özün təyin edirsən, heç kim yoxlamayacaq."},"cs":{"ime":"Karta hráče","opis":"Velká karta A5 jako ze sbírky samolepek, s tvým hodnocením. Hodnocení si určíš sám, nikdo to kontrolovat nebude."},"da":{"ime":"Spillerkort","opis":"Stort A5-kort som fra et samlealbum, med dine egne vurderinger. Du bestemmer selv tallene, ingen tjekker dem."},"de":{"ime":"Spielerkarte","opis":"Große A5-Karte wie aus dem Sammelalbum, mit deinen Werten. Die Werte bestimmst du selbst, niemand prüft nach."},"el":{"ime":"Κάρτα παίκτη","opis":"Μεγάλη κάρτα A5 σαν από άλμπουμ με χαρτάκια, με δικές σου βαθμολογίες. Τους αριθμούς τους βάζεις εσύ, κανείς δεν θα τους ελέγξει."},"es":{"ime":"Carta de jugador","opis":"Carta grande A5 como de álbum de cromos, con tus propias valoraciones. Las valoraciones las pones tú, nadie las va a comprobar."},"et":{"ime":"Mängijakaart","opis":"Suur A5 kaart nagu kleepsualbumist, sinu enda hinnetega. Hinded paned ise, keegi ei hakka kontrollima."},"hr":{"ime":"Kartica igrača","opis":"Velika kartica A5 kao iz albuma sličica, s tvojim ocjenama. Ocjene određuješ sam, nitko neće provjeravati."},"hu":{"ime":"Játékoskártya","opis":"Nagy, A5-ös kártya, mint egy matricagyűjteményből, a saját értékeiddel. Az értékeket te adod meg, senki sem fogja ellenőrizni."},"hy":{"ime":"Խաղացողի քարտ","opis":"Մեծ A5 քարտ, ինչպես կպչուն նկարների ալբոմից, քո գնահատականներով։ Գնահատականները որոշում ես դու, ոչ ոք չի ստուգի։"},"lv":{"ime":"Spēlētāja kartīte","opis":"Liela A5 kartīte kā no uzlīmju albuma, ar taviem vērtējumiem. Vērtējumus nosaki pats, neviens nepārbaudīs."},"mk":{"ime":"Картичка на играч","opis":"Голема A5 картичка како од албум со сличички, со твоите оценки. Оценките ги одредуваш сам, никој нема да проверува."},"pl":{"ime":"Karta zawodnika","opis":"Duża karta A5 jak z albumu z naklejkami, z twoimi ocenami. Oceny ustalasz sam, nikt nie będzie sprawdzał."},"ro":{"ime":"Card de jucător","opis":"Card mare A5 ca dintr-un album cu abțibilduri, cu notele tale. Notele le stabilești tu, nimeni nu le va verifica."},"sk":{"ime":"Karta hráča","opis":"Veľká karta A5 ako zo zbierky samolepiek, s tvojím hodnotením. Hodnotenia si určíš sám, nikto ich kontrolovať nebude."},"sr":{"ime":"Kartica igrača","opis":"Velika kartica A5 kao iz albuma sličica, sa tvojim ocenama. Ocene određuješ sam, niko neće proveravati."},"tr":{"ime":"Oyuncu kartı","opis":"Çıkartma albümlerindeki gibi büyük bir A5 kart, değerleri senden. Sayıları sen belirlersin, kimse kontrol etmez."},"uk":{"ime":"Картка гравця","opis":"Велика картка A5, як з альбому наліпок, із твоїми оцінками. Оцінки визначаєш сам, ніхто не перевірятиме."}}$p$::jsonb where slug = 'kartica-igralca';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Fərdi vımpel","opis":"Kapitanların oyundan əvvəl dəyişdiyi kimi saçaqlı klub vımpeli."},"cs":{"ime":"Vlaječka na míru","opis":"Klubová vlaječka se střapci, jako si je kapitáni vyměňují před zápasem."},"da":{"ime":"Vimpel med eget design","opis":"Klubvimpel med frynser, som dem anførerne bytter før kampen."},"de":{"ime":"Individueller Wimpel","opis":"Vereinswimpel mit Fransen, wie ihn die Kapitäne vor dem Anpfiff tauschen."},"el":{"ime":"Λάβαρο με εξατομίκευση","opis":"Λάβαρο συλλόγου με κρόσσια, σαν αυτά που ανταλλάσσουν οι αρχηγοί πριν από τη σέντρα."},"es":{"ime":"Banderín personalizado","opis":"Banderín de club con flecos, como los que se intercambian los capitanes antes del partido."},"et":{"ime":"Personaalne vimpel","opis":"Narmastega klubivimpel, nagu kaptenid neid enne mängu vahetavad."},"hr":{"ime":"Zastavica po mjeri","opis":"Klupska zastavica s resama, kakve kapetani razmjenjuju prije utakmice."},"hu":{"ime":"Egyedi zászló","opis":"Rojtos klubzászló, mint amilyet a csapatkapitányok cserélnek a meccs előtt."},"hy":{"ime":"Անհատական վիմպել","opis":"Ակումբային վիմպել՝ ծոպերով, ինչպիսիք ավագները փոխանակում են խաղից առաջ։"},"lv":{"ime":"Vimpelis ar savu dizainu","opis":"Kluba vimpelis ar bārkstīm, tāds, kādus kapteiņi apmaina pirms spēles."},"mk":{"ime":"Знаменце по мерка","opis":"Клупско знаменце со ресички, какви што капитените си разменуваат пред натпреварот."},"pl":{"ime":"Proporczyk z własnym wzorem","opis":"Klubowy proporczyk z frędzlami, taki, jakie kapitanowie wymieniają przed meczem."},"ro":{"ime":"Fanion personalizat","opis":"Fanion de club cu ciucuri, ca acelea pe care și le schimbă căpitanii înainte de meci."},"sk":{"ime":"Vlajočka na mieru","opis":"Klubová vlajočka so strapcami, aké si kapitáni vymieňajú pred zápasom."},"sr":{"ime":"Zastavica po meri","opis":"Klupska zastavica sa resama, kakve kapiteni razmenjuju pre utakmice."},"tr":{"ime":"Kişiye özel flama","opis":"Kaptanların başlama vuruşundan önce değiş tokuş ettiği türden püsküllü kulüp flaması."},"uk":{"ime":"Вимпел на замовлення","opis":"Клубний вимпел із китицями, як ті, якими капітани обмінюються перед матчем."}}$p$::jsonb where slug = 'zastavica-po-meri';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Fərdi atlaz şərf","opis":"Atlaz azarkeş şərfi, 140 sm, hər iki ucunda komanda adı ilə."},"cs":{"ime":"Saténová šála na míru","opis":"Saténová fanouškovská šála, 140 cm, s názvem týmu na obou koncích."},"da":{"ime":"Satinhalstørklæde med eget design","opis":"Fanhalstørklæde i satin, 140 cm, med holdnavnet i begge ender."},"de":{"ime":"Individueller Satinschal","opis":"Satin-Fanschal, 140 cm, mit dem Teamnamen an beiden Enden."},"el":{"ime":"Σατέν κασκόλ με εξατομίκευση","opis":"Σατέν κασκόλ οπαδού, 140 cm, με το όνομα της ομάδας σου και στις δύο άκρες."},"es":{"ime":"Bufanda de satén personalizada","opis":"Bufanda de aficionado de satén, 140 cm, con el nombre del equipo en los dos extremos."},"et":{"ime":"Personaalne satiinsall","opis":"Satiinist fännisall, 140 cm, meeskonna nimega mõlemas otsas."},"hr":{"ime":"Satenski šal po mjeri","opis":"Satenski navijački šal, 140 cm, s imenom ekipe na oba kraja."},"hu":{"ime":"Egyedi szatén sál","opis":"Szatén szurkolói sál, 140 cm, a csapat nevével mindkét végén."},"hy":{"ime":"Անհատական ատլասե շարֆ","opis":"Ատլասե երկրպագուի շարֆ, 140 սմ, երկու ծայրերին՝ թիմի անունով։"},"lv":{"ime":"Satīna šalle ar savu dizainu","opis":"Satīna līdzjutēju šalle, 140 cm, ar komandas nosaukumu abos galos."},"mk":{"ime":"Сатенски шал по мерка","opis":"Сатенски навивачки шал, 140 cm, со името на тимот на двата краја."},"pl":{"ime":"Satynowy szalik z własnym wzorem","opis":"Satynowy szalik kibica, 140 cm, z nazwą drużyny na obu końcach."},"ro":{"ime":"Fular din satin personalizat","opis":"Fular de suporter din satin, 140 cm, cu numele echipei la ambele capete."},"sk":{"ime":"Saténový šál na mieru","opis":"Saténový fanúšikovský šál, 140 cm, s názvom tímu na oboch koncoch."},"sr":{"ime":"Satenski šal po meri","opis":"Satenski navijački šal, 140 cm, sa imenom ekipe na oba kraja."},"tr":{"ime":"Kişiye özel saten atkı","opis":"Her iki ucunda takımının adı olan 140 cm saten taraftar atkısı."},"uk":{"ime":"Атласний шарф на замовлення","opis":"Атласний фанатський шарф, 140 см, з назвою команди на обох кінцях."}}$p$::jsonb where slug = 'sal-po-meri';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Fərdi kepka","opis":"Önündə tikmə yazı olan günlüklü kepka. Məşqçinin göstərişləri kimi qısa və aydın."},"cs":{"ime":"Kšiltovka na míru","opis":"Kšiltovka s vyšitým nápisem vpředu. Krátce a jasně, jako pokyny trenéra."},"da":{"ime":"Kasket med eget design","opis":"Kasket med skygge og broderet tekst foran. Kort og klart, som trænerens besked."},"de":{"ime":"Individuelle Cap","opis":"Schirmmütze mit gesticktem Schriftzug vorne. Kurz und klar wie die Ansage des Trainers."},"el":{"ime":"Καπέλο με εξατομίκευση","opis":"Καπέλο με κέντημα μπροστά. Σύντομο και καθαρό, όπως η ομιλία του προπονητή."},"es":{"ime":"Gorra personalizada","opis":"Gorra con visera y texto bordado delante. Corto y claro, como las instrucciones del míster."},"et":{"ime":"Personaalne nokamüts","opis":"Nokamüts tikitud kirjaga ees. Lühidalt ja selgelt, nagu treeneri juhised."},"hr":{"ime":"Kapa po mjeri","opis":"Kapa sa šiltom i vezenim natpisom sprijeda. Kratko i jasno, kao trenerove upute."},"hu":{"ime":"Egyedi sapka","opis":"Baseballsapka hímzett felirattal elöl. Röviden és érthetően, mint az edző utasításai."},"hy":{"ime":"Անհատական կեպի","opis":"Կեպի՝ առջևում ասեղնագործված գրությամբ։ Կարճ և հստակ, ինչպես մարզչի ցուցումները։"},"lv":{"ime":"Cepure ar savu dizainu","opis":"Cepure ar nagu un izšūtu uzrakstu priekšā. Īsi un skaidri, kā trenera norādījumi."},"mk":{"ime":"Капа по мерка","opis":"Капа со штитник и везен натпис напред. Кратко и јасно, како упатствата на тренерот."},"pl":{"ime":"Czapka z własnym wzorem","opis":"Czapka z daszkiem i haftowanym napisem z przodu. Krótko i jasno, jak polecenia trenera."},"ro":{"ime":"Șapcă personalizată","opis":"Șapcă cu cozoroc și inscripție brodată în față. Scurt și clar, ca indicațiile antrenorului."},"sk":{"ime":"Šiltovka na mieru","opis":"Šiltovka s vyšitým nápisom vpredu. Stručne a jasne, ako pokyny trénera."},"sr":{"ime":"Kačket po meri","opis":"Kačket sa vezenim natpisom napred. Kratko i jasno, kao uputstva trenera."},"tr":{"ime":"Kişiye özel şapka","opis":"Önü nakışlı şapka. Hocanın devre arası konuşması gibi kısa ve net."},"uk":{"ime":"Кепка на замовлення","opis":"Кепка з козирком і вишитим написом спереду. Коротко і ясно, як настанова тренера."}}$p$::jsonb where slug = 'kapa-po-meri';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Fərdi kapitan sarğısı","opis":"Fərdi yazılı və yapışqan bağlı kapitan sarğısı. Meydança pulunu yığan üçün."},"cs":{"ime":"Kapitánská páska na míru","opis":"Kapitánská páska s nápisem na míru a suchým zipem. Pro toho, kdo vybírá peníze za hřiště."},"da":{"ime":"Anførerbind med eget design","opis":"Anførerbind med din egen tekst og velcrolukning. Til ham, der samler banelejen ind."},"de":{"ime":"Individuelle Kapitänsbinde","opis":"Kapitänsbinde mit eigenem Schriftzug und Klettverschluss. Für den, der das Geld für den Platz einsammelt."},"el":{"ime":"Περιβραχιόνιο αρχηγού με εξατομίκευση","opis":"Περιβραχιόνιο αρχηγού με δικό σου κείμενο και κούμπωμα σκρατς. Για αυτόν που μαζεύει τα λεφτά για το γήπεδο."},"es":{"ime":"Brazalete de capitán personalizado","opis":"Brazalete de capitán con texto personalizado y cierre de velcro. Para el que recoge el dinero del campo."},"et":{"ime":"Personaalne kaptenipael","opis":"Kaptenipael personaalse kirja ja takjakinnisega. Sellele, kes korjab väljaku raha kokku."},"hr":{"ime":"Kapetanska traka po mjeri","opis":"Kapetanska traka s natpisom po mjeri i čičak-zatvaračem. Za onoga tko skuplja novac za teren."},"hu":{"ime":"Egyedi kapitányi karszalag","opis":"Kapitányi karszalag egyedi felirattal és tépőzárral. Annak, aki beszedi a pályapénzt."},"hy":{"ime":"Անհատական ավագի թևկապ","opis":"Ավագի թևկապ՝ անհատական գրությամբ և կպչուն ժապավենով։ Նրա համար, ով հավաքում է դաշտի վարձը։"},"lv":{"ime":"Kapteiņa apsējs ar savu dizainu","opis":"Kapteiņa apsējs ar savu uzrakstu un līplenti. Tam, kurš savāc naudu par laukumu."},"mk":{"ime":"Капитенска лента по мерка","opis":"Капитенска лента со натпис по мерка и чичак. За оној што ги собира парите за теренот."},"pl":{"ime":"Opaska kapitana z własnym wzorem","opis":"Opaska kapitana z własnym napisem i rzepem. Dla tego, kto zbiera kasę za boisko."},"ro":{"ime":"Banderolă de căpitan personalizată","opis":"Banderolă de căpitan cu inscripție personalizată și arici. Pentru cel care strânge banii pentru teren."},"sk":{"ime":"Kapitánska páska na mieru","opis":"Kapitánska páska s nápisom na mieru a suchým zipsom. Pre toho, kto vyberá peniaze za ihrisko."},"sr":{"ime":"Kapitenska traka po meri","opis":"Kapitenska traka sa natpisom po meri i čičak-trakom. Za onog ko skuplja pare za teren."},"tr":{"ime":"Kişiye özel kaptanlık pazubendi","opis":"Kendi yazınla, cırt cırtlı kaptanlık pazubendi. Saha parasını toplayan kişi için."},"uk":{"ime":"Капітанська пов’язка на замовлення","opis":"Капітанська пов’язка з власним написом і липучкою. Для того, хто збирає гроші за оренду поля."}}$p$::jsonb where slug = 'trak-po-meri';

update trgovina.izdelki set prevodi = $p${"az":{"ime":"Fərdi forma","opis":"Poliesterdən əsl yarış forması, tamamilə sublimasiya ilə çap olunub: naxış, rənglər, yaxalıq, sponsor, ad və nömrə sənin istədiyin kimi."},"cs":{"ime":"Dres na míru","opis":"Skutečný zápasový dres z polyesteru, celý potištěný sublimací: vzor, barvy, límec, sponzor, jméno a číslo po tvém."},"da":{"ime":"Spillertrøje med eget design","opis":"Ægte kamptrøje i polyester, helt sublimationstrykt: mønster, farver, krave, sponsor, navn og nummer, som du vil have det."},"de":{"ime":"Individuelles Trikot","opis":"Echtes Wettkampftrikot aus Polyester, komplett im Sublimationsdruck: Muster, Farben, Kragen, Sponsor, Name und Nummer nach deinem Geschmack."},"el":{"ime":"Ποδοσφαιρική φανέλα με εξατομίκευση","opis":"Κανονική αγωνιστική φανέλα από πολυεστέρα, με ολική εκτύπωση εξάχνωσης: σχέδιο, χρώματα, γιακάς, χορηγός, όνομα και αριθμός όπως τα θέλεις."},"es":{"ime":"Camiseta de fútbol personalizada","opis":"Una auténtica camiseta de juego de poliéster, sublimada por completo: diseño, colores, cuello, patrocinador, nombre y dorsal a tu manera."},"et":{"ime":"Personaalne mängusärk","opis":"Päris polüestrist võistlussärk, üleni sublimatsioontrükiga: muster, värvid, krae, sponsor, nimi ja number sinu valikul."},"hr":{"ime":"Dres po mjeri","opis":"Pravi natjecateljski dres od poliestera, cijeli otisnut sublimacijom: uzorak, boje, ovratnik, sponzor, ime i broj po tvom."},"hu":{"ime":"Egyedi mez","opis":"Igazi poliészter versenymez, teljes felületén szublimációval nyomtatva: minta, színek, gallér, szponzor, név és szám a saját ízlésed szerint."},"hy":{"ime":"Անհատական մարզաշապիկ","opis":"Իսկական մրցութային մարզաշապիկ պոլիեսթերից՝ ամբողջությամբ սուբլիմացիոն տպագրությամբ. նախշ, գույներ, օձիք, հովանավոր, անուն և համար՝ քո ձևով։"},"lv":{"ime":"Futbola krekls ar savu dizainu","opis":"Īsts poliestera spēļu krekls, pilnībā apdrukāts ar sublimāciju: raksts, krāsas, apkakle, sponsors, vārds un numurs pēc tava prāta."},"mk":{"ime":"Дрес по мерка","opis":"Вистински натпреварувачки дрес од полиестер, целиот печатен со сублимација: шема, бои, јака, спонзор, име и број по твое."},"pl":{"ime":"Koszulka meczowa z własnym wzorem","opis":"Prawdziwa meczowa koszulka z poliestru, w całości zadrukowana sublimacyjnie: wzór, kolory, kołnierzyk, sponsor, nazwisko i numer po twojemu."},"ro":{"ime":"Echipament personalizat","opis":"Tricou de joc adevărat din poliester, imprimat integral prin sublimare: model, culori, guler, sponsor, nume și număr după gustul tău."},"sk":{"ime":"Dres na mieru","opis":"Skutočný zápasový dres z polyesteru, celý potlačený sublimáciou: vzor, farby, golier, sponzor, meno a číslo po tvojom."},"sr":{"ime":"Dres po meri","opis":"Pravi takmičarski dres od poliestera, ceo odštampan sublimacijom: šara, boje, kragna, sponzor, ime i broj po tvom."},"tr":{"ime":"Kişiye özel forma","opis":"Baştan sona süblimasyon baskılı gerçek polyester maç forması: desen, renkler, yaka, sponsor, isim ve numara senin tercihinle."},"uk":{"ime":"Ігрова футболка на замовлення","opis":"Справжня ігрова футболка з поліестеру, повністю надрукована методом сублімації: візерунок, кольори, комір, спонсор, ім’я та номер на твій смак."}}$p$::jsonb where slug = 'dres-po-meri';

