-- Motivi: ime, opis, primeri; polja in sheme dobijo prevode v vrstici
-- (polje: {kljuc: {oznaka_de, privzeto_de, moznosti_de …, "_moznosti": {kljuc možnosti: {ime_de …}}}},
-- shema: {kljuc: {ime_de …}}). Začasna funkcija jih doda obstoječim poljem.
create function pg_temp.s_prevodi(p_polja jsonb, p jsonb) returns jsonb
language sql immutable
as $$
  select coalesce(jsonb_agg(
           (f || coalesce(p->(f->>'kljuc'), '{}') - '_moznosti')
           || case when jsonb_typeof(f->'moznosti') = 'array' and p->(f->>'kljuc') ? '_moznosti' then
                jsonb_build_object('moznosti', (
                  select jsonb_agg(case when jsonb_typeof(o) = 'object'
                                        then o || coalesce(p->(f->>'kljuc')->'_moznosti'->(o->>'kljuc'), '{}')
                                        else o end order by n)
                    from jsonb_array_elements(f->'moznosti') with ordinality y(o, n)))
              else '{}'::jsonb end
           order by i), '[]'::jsonb)
    from jsonb_array_elements(p_polja) with ordinality x(f, i)
$$;
create function pg_temp.s_sheme(p_sheme jsonb, p jsonb) returns jsonb
language sql immutable
as $$
  select coalesce(jsonb_agg(s || coalesce(p->(s->>'kljuc'), '{}') order by i), '[]'::jsonb)
    from jsonb_array_elements(p_sheme) with ordinality x(s, i)
$$;

