update trgovina.motivi set prevodi = $p${"en":{"primeri":[{"barva":"Črna","polja":{"ime":"WILLIAMS","leto":1994,"vzdevek":"Old Fox"},"shema":"zlata-doba","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"ime":"WILSON","leto":2009,"vzdevek":"Turbo"},"shema":"modra-kri","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"EVANS","leto":1989,"vzdevek":"The Wall"},"shema":"nocna","izdelek":"pulover-po-meri"}]},"az":{"ime":"Bazar liqası əfsanəsi","opis":"Əzəldən oynayan və hələ də meydançaya birinci gələn üçün. Ad, bütün kəndin tanıdığı ləqəb və hər şeyin başladığı il.","primeri":[{"barva":"Črna","polja":{"ime":"HƏSƏNOV","leto":1994,"vzdevek":"Qoca Tülkü"},"shema":"zlata-doba","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"ime":"İSMAYILOV","leto":2009,"vzdevek":"Turbo"},"shema":"modra-kri","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"CƏFƏROV","leto":1989,"vzdevek":"Divar"},"shema":"nocna","izdelek":"pulover-po-meri"}]},"cs":{"ime":"Legenda nedělní ligy","opis":"Pro toho, kdo hraje odjakživa a pořád přichází na hřiště první. Jméno, přezdívka, kterou zná celá vesnice, a rok, kdy to všechno začalo.","primeri":[{"barva":"Črna","polja":{"ime":"PROCHÁZKA","leto":1994,"vzdevek":"Stará liška"},"shema":"zlata-doba","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"ime":"KUČERA","leto":2009,"vzdevek":"Turbo"},"shema":"modra-kri","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"VESELÝ","leto":1989,"vzdevek":"Zeď"},"shema":"nocna","izdelek":"pulover-po-meri"}]},"da":{"ime":"Søndagsligaens legende","opis":"Til ham, der har spillet altid og stadig er den første på banen. Navn, kælenavnet, som hele landsbyen kender, og året, hvor det hele begyndte.","primeri":[{"barva":"Črna","polja":{"ime":"ANDERSEN","leto":1994,"vzdevek":"Gamle Ræv"},"shema":"zlata-doba","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"ime":"MØLLER","leto":2009,"vzdevek":"Turbo"},"shema":"modra-kri","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"LARSEN","leto":1989,"vzdevek":"Muren"},"shema":"nocna","izdelek":"pulover-po-meri"}]},"de":{"ime":"Sonntagsliga-Legende","opis":"Für den, der schon ewig spielt und trotzdem als Erster am Platz ist. Name, der Spitzname, den das ganze Dorf kennt, und das Jahr, in dem alles anfing.","primeri":[{"barva":"Črna","polja":{"ime":"WEBER","leto":1994,"vzdevek":"Alter Fuchs"},"shema":"zlata-doba","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"ime":"MEYER","leto":2009,"vzdevek":"Turbo"},"shema":"modra-kri","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"WAGNER","leto":1989,"vzdevek":"Die Mauer"},"shema":"nocna","izdelek":"pulover-po-meri"}]},"el":{"ime":"Θρύλος της Κυριακής","opis":"Για αυτόν που παίζει από πάντα και είναι ακόμα πρώτος στο γήπεδο. Όνομα, το παρατσούκλι που ξέρει όλο το χωριό και η χρονιά που ξεκίνησαν όλα.","primeri":[{"barva":"Črna","polja":{"ime":"ΟΙΚΟΝΟΜΟΥ","leto":1994,"vzdevek":"Γερο-αλεπού"},"shema":"zlata-doba","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"ime":"ΜΑΚΡΗΣ","leto":2009,"vzdevek":"Τούρμπο"},"shema":"modra-kri","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"ΙΩΑΝΝΙΔΗΣ","leto":1989,"vzdevek":"Τοίχος"},"shema":"nocna","izdelek":"pulover-po-meri"}]},"es":{"ime":"Leyenda de la liga de domingo","opis":"Para el que juega desde siempre y sigue siendo el primero en llegar al campo. Nombre, el apodo que conoce todo el pueblo y el año en que empezó todo.","primeri":[{"barva":"Črna","polja":{"ime":"PÉREZ","leto":1994,"vzdevek":"Viejo Zorro"},"shema":"zlata-doba","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"ime":"FERNÁNDEZ","leto":2009,"vzdevek":"Turbo"},"shema":"modra-kri","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"GÓMEZ","leto":1989,"vzdevek":"El Muro"},"shema":"nocna","izdelek":"pulover-po-meri"}]},"et":{"ime":"Pühapäevaliiga legend","opis":"Sellele, kes on mänginud juba igavesti ja jõuab ikka esimesena väljakule. Nimi, hüüdnimi, mida teab terve küla, ja aasta, mil kõik algas.","primeri":[{"barva":"Črna","polja":{"ime":"KASK","leto":1994,"vzdevek":"Vana Hunt"},"shema":"zlata-doba","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"ime":"KUUSK","leto":2009,"vzdevek":"Turbo"},"shema":"modra-kri","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"ILVES","leto":1989,"vzdevek":"Müür"},"shema":"nocna","izdelek":"pulover-po-meri"}]},"hr":{"ime":"Legenda nedjeljne lige","opis":"Za onoga tko igra otkad zna za sebe i još uvijek prvi dolazi na teren. Ime, nadimak koji zna cijelo selo i godina kad je sve počelo.","primeri":[{"barva":"Črna","polja":{"ime":"JURIĆ","leto":1994,"vzdevek":"Stara lisica"},"shema":"zlata-doba","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"ime":"KNEŽEVIĆ","leto":2009,"vzdevek":"Turbo"},"shema":"modra-kri","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"PERIĆ","leto":1989,"vzdevek":"Zid"},"shema":"nocna","izdelek":"pulover-po-meri"}]},"hu":{"ime":"A vasárnapi bajnokság legendája","opis":"Annak, aki öröktől fogva játszik, és még mindig elsőként ér ki a pályára. Név, becenév, amelyet az egész falu ismer, és az év, amikor minden elkezdődött.","primeri":[{"barva":"Črna","polja":{"ime":"HORVÁTH","leto":1994,"vzdevek":"Vén Róka"},"shema":"zlata-doba","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"ime":"VARGA","leto":2009,"vzdevek":"Turbó"},"shema":"modra-kri","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"KISS","leto":1989,"vzdevek":"A Fal"},"shema":"nocna","izdelek":"pulover-po-meri"}]},"hy":{"ime":"Կիրակնօրյա լիգայի լեգենդ","opis":"Նրա համար, ով խաղում է անհիշելի ժամանակներից և դեռ առաջինն է գալիս դաշտ։ Անուն, մականուն, որը գիտի ամբողջ գյուղը, և տարին, երբ ամեն ինչ սկսվեց։","primeri":[{"barva":"Črna","polja":{"ime":"ԱՎԵՏԻՍՅԱՆ","leto":1994,"vzdevek":"Ծեր աղվես"},"shema":"zlata-doba","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"ime":"ՄԿՐՏՉՅԱՆ","leto":2009,"vzdevek":"Տուրբո"},"shema":"modra-kri","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"ԽԱՉԱՏՐՅԱՆ","leto":1989,"vzdevek":"Պատ"},"shema":"nocna","izdelek":"pulover-po-meri"}]},"lv":{"ime":"Svētdienas līgas leģenda","opis":"Tam, kurš spēlē jau kopš sendienām un joprojām pirmais ierodas laukumā. Vārds, iesauka, ko zina viss ciems, un gads, kad viss sākās.","primeri":[{"barva":"Črna","polja":{"ime":"LIEPIŅŠ","leto":1994,"vzdevek":"Vecā Lapsa"},"shema":"zlata-doba","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"ime":"KRŪMIŅŠ","leto":2009,"vzdevek":"Turbo"},"shema":"modra-kri","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"ZARIŅŠ","leto":1989,"vzdevek":"Siena"},"shema":"nocna","izdelek":"pulover-po-meri"}]},"mk":{"ime":"Легенда на неделната лига","opis":"За оној што игра од памтивек и сè уште прв доаѓа на теренот. Име, прекар што го знае цело село и годината кога сè почна.","primeri":[{"barva":"Črna","polja":{"ime":"ЈОВАНОВСКИ","leto":1994,"vzdevek":"Стариот лисец"},"shema":"zlata-doba","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"ime":"ДИМИТРОВ","leto":2009,"vzdevek":"Турбо"},"shema":"modra-kri","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"ГЕОРГИЕВСКИ","leto":1989,"vzdevek":"Ѕидот"},"shema":"nocna","izdelek":"pulover-po-meri"}]},"pl":{"ime":"Legenda niedzielnej ligi","opis":"Dla tego, kto gra od zawsze i wciąż pierwszy przychodzi na boisko. Nazwisko, ksywka, którą zna cała wieś, i rok, w którym wszystko się zaczęło.","primeri":[{"barva":"Črna","polja":{"ime":"KAMIŃSKI","leto":1994,"vzdevek":"Stary Lis"},"shema":"zlata-doba","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"ime":"DĄBROWSKI","leto":2009,"vzdevek":"Turbo"},"shema":"modra-kri","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"KOZŁOWSKI","leto":1989,"vzdevek":"Mur"},"shema":"nocna","izdelek":"pulover-po-meri"}]},"ro":{"ime":"Legenda ligii de duminică","opis":"Pentru cel care joacă de când lumea și tot el ajunge primul pe teren. Numele, porecla pe care o știe tot satul și anul în care a început totul.","primeri":[{"barva":"Črna","polja":{"ime":"STAN","leto":1994,"vzdevek":"Vulpea Bătrână"},"shema":"zlata-doba","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"ime":"CONSTANTIN","leto":2009,"vzdevek":"Turbo"},"shema":"modra-kri","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"GHEORGHE","leto":1989,"vzdevek":"Zidul"},"shema":"nocna","izdelek":"pulover-po-meri"}]},"sk":{"ime":"Legenda nedeľnej ligy","opis":"Pre toho, kto hrá odjakživa a stále prichádza na ihrisko prvý. Meno, prezývka, ktorú pozná celá dedina, a rok, keď sa to všetko začalo.","primeri":[{"barva":"Črna","polja":{"ime":"TÓTH","leto":1994,"vzdevek":"Stará líška"},"shema":"zlata-doba","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"ime":"BALÁŽ","leto":2009,"vzdevek":"Turbo"},"shema":"modra-kri","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"MOLNÁR","leto":1989,"vzdevek":"Múr"},"shema":"nocna","izdelek":"pulover-po-meri"}]},"sr":{"ime":"Legenda nedeljne lige","opis":"Za onog ko igra otkad zna za sebe i još uvek prvi stiže na teren. Ime, nadimak koji zna celo selo i godina kad je sve počelo.","primeri":[{"barva":"Črna","polja":{"ime":"ĐORĐEVIĆ","leto":1994,"vzdevek":"Stara lisica"},"shema":"zlata-doba","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"ime":"STOJANOVIĆ","leto":2009,"vzdevek":"Turbo"},"shema":"modra-kri","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"ILIĆ","leto":1989,"vzdevek":"Zid"},"shema":"nocna","izdelek":"pulover-po-meri"}]},"tr":{"ime":"Pazar Ligi Efsanesi","opis":"Ezelden beri oynayan ve sahaya hâlâ ilk gelen kişi için. İsim, bütün köyün bildiği lakap ve her şeyin başladığı yıl.","primeri":[{"barva":"Črna","polja":{"ime":"ÇELİK","leto":1994,"vzdevek":"Yaşlı Kurt"},"shema":"zlata-doba","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"ime":"YILDIZ","leto":2009,"vzdevek":"Turbo"},"shema":"modra-kri","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"ÖZTÜRK","leto":1989,"vzdevek":"Duvar"},"shema":"nocna","izdelek":"pulover-po-meri"}]},"uk":{"ime":"Легенда недільної ліги","opis":"Для того, хто грає відколи себе пам’ятає і досі першим приходить на поле. Ім’я, прізвисько, яке знає все село, і рік, коли все почалося.","primeri":[{"barva":"Črna","polja":{"ime":"МЕЛЬНИК","leto":1994,"vzdevek":"Старий лис"},"shema":"zlata-doba","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"ime":"КРАВЧЕНКО","leto":2009,"vzdevek":"Турбо"},"shema":"modra-kri","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"ОЛІЙНИК","leto":1989,"vzdevek":"Стіна"},"shema":"nocna","izdelek":"pulover-po-meri"}]}}$p$::jsonb,
