  sheme = pg_temp.s_sheme(sheme, $p${"jutro-po":{"ime_az":"Səhəri gün","ime_cs":"Ráno potom","ime_da":"Morgenen efter","ime_de":"Der Morgen danach","ime_el":"Το πρωί μετά","ime_es":"La mañana después","ime_et":"Järgmine hommik","ime_hr":"Jutro poslije","ime_hu":"Másnap reggel","ime_hy":"Հաջորդ առավոտ","ime_lv":"Nākamais rīts","ime_mk":"Утрото потоа","ime_pl":"Poranek po","ime_ro":"Dimineața de după","ime_sk":"Ráno potom","ime_sr":"Jutro posle","ime_tr":"Ertesi sabah","ime_uk":"Ранок після"},"pivska":{"ime_az":"Pivə kəhrəbası","ime_cs":"Pivní jantarová","ime_da":"Ravgul øl","ime_de":"Bier-Bernstein","ime_el":"Κεχριμπαρένια μπίρα","ime_es":"Ámbar cervecero","ime_et":"Õllemerevaik","ime_hr":"Pivska jantarna","ime_hu":"Sörborostyán","ime_hy":"Գարեջրի սաթ","ime_lv":"Alus dzintars","ime_mk":"Пивска килибарна","ime_pl":"Piwny bursztyn","ime_ro":"Chihlimbar de bere","ime_sk":"Pivová jantárová","ime_sr":"Pivska jantarna","ime_tr":"Bira kehribarı","ime_uk":"Пивна бурштинова"},"nocna":{"ime_az":"Gecə qara-qızılı","ime_cs":"Noční černo-zlatá","ime_da":"Nat sort-guld","ime_de":"Nacht Schwarz-Gold","ime_el":"Νυχτερινό μαύρο-χρυσό","ime_es":"Noche negro y oro","ime_et":"Öine must-kuldne","ime_hr":"Noćna crno-zlatna","ime_hu":"Éjszakai fekete-arany","ime_hy":"Գիշերային սև-ոսկեգույն","ime_lv":"Nakts melni zelta","ime_mk":"Ноќна црно-златна","ime_pl":"Nocna czarno-złota","ime_ro":"Noapte negru-auriu","ime_sk":"Nočná čierno-zlatá","ime_sr":"Noćna crno-zlatna","ime_tr":"Gece siyah-altın","ime_uk":"Нічна чорно-золота"}}$p$::jsonb)
