update trgovina.motivi set prevodi = $p${"en":{"primeri":[{"barva":"Bela","polja":{"ime":"DAVIES","stevilka":5},"shema":"kapetanska","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"MURPHY","stevilka":1},"shema":"klasika","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"THOMAS","stevilka":14},"shema":"nocna","izdelek":"pulover-po-meri"}]},"az":{"ime":"Kapitan","opis":"Qolda \"C\" sarğısı, arxada ad və nömrə. Meydança pulunu yığan, hakimi adı ilə çağıran və oyundan sonra topu götürən üçün.","primeri":[{"barva":"Bela","polja":{"ime":"ABBASOV","stevilka":5},"shema":"kapetanska","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"RZAYEV","stevilka":1},"shema":"klasika","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"NƏBİYEV","stevilka":14},"shema":"nocna","izdelek":"pulover-po-meri"}]},"cs":{"ime":"Kapitán","opis":"Páska „C“ na rukávu, jméno a číslo na zádech. Pro toho, kdo vybírá peníze za hřiště, oslovuje rozhodčího jménem a po zápase sbírá míč.","primeri":[{"barva":"Bela","polja":{"ime":"HORÁK","stevilka":5},"shema":"kapetanska","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"NĚMEC","stevilka":1},"shema":"klasika","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"POKORNÝ","stevilka":14},"shema":"nocna","izdelek":"pulover-po-meri"}]},"da":{"ime":"Kaptajn","opis":"Bind med \"C\" på ærmet, navn og nummer på ryggen. Til ham, der samler banelejen ind, kalder dommeren ved fornavn og tager bolden med hjem efter kampen.","primeri":[{"barva":"Bela","polja":{"ime":"SØRENSEN","stevilka":5},"shema":"kapetanska","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"RASMUSSEN","stevilka":1},"shema":"klasika","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"JØRGENSEN","stevilka":14},"shema":"nocna","izdelek":"pulover-po-meri"}]},"de":{"ime":"Kapitän","opis":"Binde mit \"C\" am Ärmel, Name und Nummer auf dem Rücken. Für den, der das Geld für den Platz einsammelt, den Schiri beim Vornamen nennt und nach dem Spiel den Ball mitnimmt.","primeri":[{"barva":"Bela","polja":{"ime":"BECKER","stevilka":5},"shema":"kapetanska","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"HOFMANN","stevilka":1},"shema":"klasika","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"SCHULZ","stevilka":14},"shema":"nocna","izdelek":"pulover-po-meri"}]},"el":{"ime":"Αρχηγός","opis":"Το περιβραχιόνιο με το «C» στο μανίκι, όνομα και αριθμός στην πλάτη. Για αυτόν που μαζεύει τα λεφτά για το γήπεδο, ξέρει τον διαιτητή με το όνομα και παίρνει την μπάλα σπίτι.","primeri":[{"barva":"Bela","polja":{"ime":"ΒΛΑΧΟΣ","stevilka":5},"shema":"kapetanska","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"ΣΤΑΘΗΣ","stevilka":1},"shema":"klasika","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"ΑΘΑΝΑΣΙΟΥ","stevilka":14},"shema":"nocna","izdelek":"pulover-po-meri"}]},"es":{"ime":"Capitán","opis":"El brazalete con la \"C\" en la manga, nombre y dorsal en la espalda. Para el que recoge el dinero del campo, llama al árbitro por su nombre y se lleva el balón a casa después del partido.","primeri":[{"barva":"Bela","polja":{"ime":"RUIZ","stevilka":5},"shema":"kapetanska","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"DÍAZ","stevilka":1},"shema":"klasika","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"MORENO","stevilka":14},"shema":"nocna","izdelek":"pulover-po-meri"}]},"et":{"ime":"Kapten","opis":"Kaptenipael \"C\" varrukal, nimi ja number seljal. Sellele, kes korjab väljaku raha kokku, kutsub kohtunikku eesnimega ja viib pärast mängu palli koju.","primeri":[{"barva":"Bela","polja":{"ime":"REBANE","stevilka":5},"shema":"kapetanska","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"LEPP","stevilka":1},"shema":"klasika","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"PÄRN","stevilka":14},"shema":"nocna","izdelek":"pulover-po-meri"}]},"hr":{"ime":"Kapetan","opis":"Traka \"C\" na rukavu, ime i broj na leđima. Za onoga tko skuplja novac za teren, zove suca po imenu i nosi loptu kući nakon utakmice.","primeri":[{"barva":"Bela","polja":{"ime":"PAVLOVIĆ","stevilka":5},"shema":"kapetanska","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"TOMIĆ","stevilka":1},"shema":"klasika","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"VUKOVIĆ","stevilka":14},"shema":"nocna","izdelek":"pulover-po-meri"}]},"hu":{"ime":"Csapatkapitány","opis":"„C” karszalag az ujjon, név és szám a háton. Annak, aki beszedi a pályapénzt, keresztnevén szólítja a bírót, és a meccs után összeszedi a labdát.","primeri":[{"barva":"Bela","polja":{"ime":"MOLNÁR","stevilka":5},"shema":"kapetanska","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"NÉMETH","stevilka":1},"shema":"klasika","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"FARKAS","stevilka":14},"shema":"nocna","izdelek":"pulover-po-meri"}]},"hy":{"ime":"Ավագ","opis":"Թևին՝ «C» թևկապ, մեջքին՝ անուն և համար։ Նրա համար, ով հավաքում է դաշտի վարձը, մրցավարին դիմում է անունով և խաղից հետո վերցնում գնդակը։","primeri":[{"barva":"Bela","polja":{"ime":"ՄԱՐԳԱՐՅԱՆ","stevilka":5},"shema":"kapetanska","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"ՍԻՄՈՆՅԱՆ","stevilka":1},"shema":"klasika","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"ՂԱԶԱՐՅԱՆ","stevilka":14},"shema":"nocna","izdelek":"pulover-po-meri"}]},"lv":{"ime":"Kapteinis","opis":"Apsējs “C” uz piedurknes, vārds un numurs uz muguras. Tam, kurš savāc naudu par laukumu, uzrunā tiesnesi vārdā un pēc spēles paņem bumbu.","primeri":[{"barva":"Bela","polja":{"ime":"PĒTERSONS","stevilka":5},"shema":"kapetanska","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"VĪTOLS","stevilka":1},"shema":"klasika","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"KLAVIŅŠ","stevilka":14},"shema":"nocna","izdelek":"pulover-po-meri"}]},"mk":{"ime":"Капитен","opis":"Лента „C“ на ракавот, име и број на грбот. За оној што ги собира парите за теренот, го вика судијата по име и ја зема топката по натпреварот.","primeri":[{"barva":"Bela","polja":{"ime":"ИЛИЕВСКИ","stevilka":5},"shema":"kapetanska","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"ВЕЛКОВ","stevilka":1},"shema":"klasika","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"СТОЈКОВСКИ","stevilka":14},"shema":"nocna","izdelek":"pulover-po-meri"}]},"pl":{"ime":"Kapitan","opis":"Opaska „C” na rękawie, nazwisko i numer na plecach. Dla tego, kto zbiera kasę za boisko, mówi do sędziego po imieniu i zabiera piłkę po meczu.","primeri":[{"barva":"Bela","polja":{"ime":"MAZUR","stevilka":5},"shema":"kapetanska","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"KRAWCZYK","stevilka":1},"shema":"klasika","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"JANKOWSKI","stevilka":14},"shema":"nocna","izdelek":"pulover-po-meri"}]},"ro":{"ime":"Căpitan","opis":"Banderola „C” pe mânecă, nume și număr pe spate. Pentru cel care strânge banii pentru teren, îl strigă pe arbitru pe nume și ia mingea acasă după meci.","primeri":[{"barva":"Bela","polja":{"ime":"MUNTEANU","stevilka":5},"shema":"kapetanska","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"RADU","stevilka":1},"shema":"klasika","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"MATEI","stevilka":14},"shema":"nocna","izdelek":"pulover-po-meri"}]},"sk":{"ime":"Kapitán","opis":"Páska „C“ na rukáve, meno a číslo na chrbte. Pre toho, kto vyberá peniaze za ihrisko, oslovuje rozhodcu menom a po zápase zbiera loptu.","primeri":[{"barva":"Bela","polja":{"ime":"LUKÁČ","stevilka":5},"shema":"kapetanska","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"ONDRUŠ","stevilka":1},"shema":"klasika","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"ime":"KRAJČÍR","stevilka":14},"shema":"nocna","izdelek":"pulover-po-meri"}]},"sr":{"ime":"Kapiten","opis":"Traka \"C\" na rukavu, ime i broj na leđima. Za onog ko skuplja pare za teren, zove sudiju po imenu i nosi loptu kući posle utakmice.","prime