update trgovina.motivi set prevodi = $p${"en":{"primeri":[{"barva":"Črna","polja":{"prvak":"Mini league champion The Bar Stool League 2025/26"},"shema":"zlata","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"prvak":"Mini league champion Office United 2024/25"},"shema":"srebrna","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"prvak":"Mini league champion Sofa Cup 2025/26"},"shema":"zelena","izdelek":"pulover-po-meri"}]},"az":{"ime":"Mini-liqa çempionu","opis":"Mini-liqanı qazandın və qrupda hamı bunu bilir — indi görəcəklər də. Liqan və mövsümünlə yazını nəticələrdən özümüz tərtib edirik.","primeri":[{"barva":"Črna","polja":{"prvak":"Mini league champion Piştaxta Liqası 2025/26"},"shema":"zlata","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"prvak":"Mini league champion Ofis Yunayted 2024/25"},"shema":"srebrna","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"prvak":"Mini league champion Divan Kuboku 2025/26"},"shema":"zelena","izdelek":"pulover-po-meri"}]},"cs":{"ime":"Šampion miniligy","opis":"Vyhrál jsi miniligu a všichni ve skupině to vědí — teď to ještě uvidí. Nápis s tvou ligou a sezónou sestavíme sami, z výsledků.","primeri":[{"barva":"Črna","polja":{"prvak":"Mini league champion Liga u Výčepu 2025/26"},"shema":"zlata","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"prvak":"Mini league champion Kancl United 2024/25"},"shema":"srebrna","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"prvak":"Mini league champion Gauč Cup 2025/26"},"shema":"zelena","izdelek":"pulover-po-meri"}]},"da":{"ime":"Miniligamester","opis":"Du vandt miniligaen, og alle i gruppen ved det — nu kan de også se det. Teksten med din liga og sæson sætter vi selv sammen ud fra resultaterne.","primeri":[{"barva":"Črna","polja":{"prvak":"Mini league champion Ligaen ved Disken 2025/26"},"shema":"zlata","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"prvak":"Mini league champion Kontoret United 2024/25"},"shema":"srebrna","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"prvak":"Mini league champion Sofa Cup 2025/26"},"shema":"zelena","izdelek":"pulover-po-meri"}]},"de":{"ime":"Mini-Liga-Meister","opis":"Du hast die Mini-Liga gewonnen und alle in der Gruppe wissen es — jetzt sehen sie es auch. Den Schriftzug mit deiner Liga und Saison setzen wir selbst aus den Ergebnissen zusammen.","primeri":[{"barva":"Črna","polja":{"prvak":"Mini league champion Tresenliga 2025/26"},"shema":"zlata","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"prvak":"Mini league champion Büro United 2024/25"},"shema":"srebrna","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"prvak":"Mini league champion Sofa Cup 2025/26"},"shema":"zelena","izdelek":"pulover-po-meri"}]},"el":{"ime":"Πρωταθλητής μίνι λίγκας","opis":"Κέρδισες τη μίνι λίγκα και το ξέρουν όλοι στο ομαδικό chat — τώρα θα το δουν κιόλας. Τη γραμμή με τη λίγκα και τη σεζόν σου τη φτιάχνουμε από τα αποτελέσματα.","primeri":[{"barva":"Črna","polja":{"prvak":"Mini league champion Λίγκα του Καφενείου 2025/26"},"shema":"zlata","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"prvak":"Mini league champion Γραφείο Γιουνάιτεντ 2024/25"},"shema":"srebrna","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"prvak":"Mini league champion Κύπελλο Καναπέ 2025/26"},"shema":"zelena","izdelek":"pulover-po-meri"}]},"es":{"ime":"Campeón de miniliga","opis":"Has ganado la miniliga y todos en el grupo lo saben: ahora además lo verán. El texto con tu liga y temporada lo componemos nosotros a partir de los resultados.","primeri":[{"barva":"Črna","polja":{"prvak":"Mini league champion Liga de la Barra 2025/26"},"shema":"zlata","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"prvak":"Mini league champion Oficina United 2024/25"},"shema":"srebrna","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"prvak":"Mini league champion Copa del Sofá 2025/26"},"shema":"zelena","izdelek":"pulover-po-meri"}]},"et":{"ime":"Miniliiga meister","opis":"Võitsid miniliiga ja kõik grupis teavad seda — nüüd nad ka näevad seda. Sinu liiga ja hooajaga kirja paneme ise kokku tulemuste põhjal.","primeri":[{"barva":"Črna","polja":{"prvak":"Mini league champion Leti Ääre Liiga 2025/26"},"shema":"zlata","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"prvak":"Mini league champion Kontor United 2024/25"},"shema":"srebrna","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"prvak":"Mini league champion Diivani Karikas 2025/26"},"shema":"zelena","izdelek":"pulover-po-meri"}]},"hr":{"ime":"Prvak mini lige","opis":"Osvojio si mini ligu i svi u grupi to znaju — sad će to i vidjeti. Natpis s tvojom ligom i sezonom slažemo sami, iz rezultata.","primeri":[{"barva":"Črna","polja":{"prvak":"Mini league champion Liga za Šankom 2025/26"},"shema":"zlata","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"prvak":"Mini league champion Ured United 2024/25"},"shema":"srebrna","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"prvak":"Mini league champion Kauč Kup 2025/26"},"shema":"zelena","izdelek":"pulover-po-meri"}]},"hu":{"ime":"Miniliga-bajnok","opis":"Megnyerted a miniligát, és a csoportban mindenki tudja — most már látni is fogják. A ligád nevével és a szezonnal ellátott feliratot mi állítjuk össze az eredményekből.","primeri":[{"barva":"Črna","polja":{"prvak":"Mini league champion Söntés Liga 2025/26"},"shema":"zlata","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"prvak":"Mini league champion Iroda United 2024/25"},"shema":"srebrna","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"prvak":"Mini league champion Kanapé Kupa 2025/26"},"shema":"zelena","izdelek":"pulover-po-meri"}]},"hy":{"ime":"Մինի լիգայի չեմպիոն","opis":"Հաղթել ես մինի լիգայում, և խմբում բոլորը դա գիտեն — հիմա նաև կտեսնեն։ Գրությունը քո լիգայով և մրցաշրջանով կազմում ենք ինքներս՝ արդյունքներից։","primeri":[{"barva":"Črna","polja":{"prvak":"Mini league champion Գարեջրատան լիգա 2025/26"},"shema":"zlata","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"prvak":"Mini league champion Գրասենյակ Յունայթեդ 2024/25"},"shema":"srebrna","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"prvak":"Mini league champion Բազմոցի գավաթ 2025/26"},"shema":"zelena","izdelek":"pulover-po-meri"}]},"lv":{"ime":"Minilīgas čempions","opis":"Tu uzvarēji minilīgā, un visi grupā to zina — tagad viņi to arī redzēs. Uzrakstu ar tavu līgu un sezonu saliekam paši, no rezultātiem.","primeri":[{"barva":"Črna","polja":{"prvak":"Mini league champion Līga pie Bāra 2025/26"},"shema":"zlata","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"prvak":"Mini league champion Birojs United 2024/25"},"shema":"srebrna","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"prvak":"Mini league champion Dīvāna Kauss 2025/26"},"shema":"zelena","izdelek":"pulover-po-meri"}]},"mk":{"ime":"Шампион на мини лига","opis":"Ја освои мини лигата и сите во групата го знаат тоа — сега ќе го видат. Натписот со твојата лига и сезона го составуваме сами, од резултатите.","primeri":[{"barva":"Črna","polja":{"prvak":"Mini league champion Лига кај Шанкот 2025/26"},"shema":"zlata","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"prvak":"Mini league champion Канцеларија Јунајтед 2024/25"},"shema":"srebrna","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"prvak":"Mini league champion Софа Куп 2025/26"},"shema":"zelena","izdelek":"pulover-po-meri"}]},"pl":{"ime":"Mistrz miniligi","opis":"Wygrałeś miniligę i wszyscy na grupie o tym wiedzą — teraz jeszcze to zobaczą. Napis z twoją ligą i sezonem składamy sami, z wyników.","primeri":[{"barva":"Črna","polja":{"prvak":"Mini league champion Liga przy Barze 2025/26"},"shema":"zlata","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"prvak":"Mini league champion Biuro United 2024/25"},"shema":"srebrna","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"prvak":"Mini league champion Puchar Kanapy 2025/26"},"shema":"zelena","izdelek":"pulover-po-meri"}]},"ro":{"ime":"Campion de mini-ligă","opis":"Ai câștigat mini-liga și toți din grup știu asta — acum o vor și vedea. Inscripția cu liga și sezonul tău o compunem noi, din rezultate.","primeri":[{"barva":"Črna","polja":{"prvak":"Mini league champion Liga de la Tejghea 2025/26"},"shema":"zlata","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"prvak":"Mini league champion Birou United 2024/25"},"shema":"srebrna","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"prvak":"Mini league champion Cupa Canapelei 2025/26"},"shema":"zelena","izdelek":"pulover-po-meri"}]},"sk":{"ime":"Šampión mini ligy","opis":"Vyhral si mini ligu a všetci v skupine to vedia — teraz to ešte aj uvidia. Nápis s tvojou ligou a sezónou zostavíme sami, z výsledkov.","primeri":[{"barva":"Črna","polja":{"prvak":"Mini league champion Liga pri Výčape 2025/26"},"shema":"zlata","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"prvak":"Mini league champion Kancel United 2024/25"},"shema":"srebrna","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"prvak":"Mini league champion Gauč Cup 2025/26"},"shema":"zelena","izdelek":"pulover-po-meri"}]},"sr":{"ime":"Šampion mini lige","opis":"Osvojio si mini ligu i svi u grupi to znaju — sad će to i videti. Natpis sa tvojom ligom i sezonom slažemo sami, iz rezultata.","primeri":[{"barva":"Črna","polja":{"prvak":"Mini league champion Liga za Šankom 2025/26"},"shema":"zlata","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"prvak":"Mini league champion Kancelarija United 2024/25"},"shema":"srebrna","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"prvak":"Mini league champion Kauč Kup 2025/26"},"shema":"zelena","izdelek":"pulover-po-meri"}]},"tr":{"ime":"Mini Lig Şampiyonu","opis":"Mini ligi kazandın ve gruptaki herkes bunu biliyor — artık görecekler de. Lig ve sezon satırını sonuçlardan biz oluştururuz.","primeri":[{"barva":"Črna","polja":{"prvak":"Mini league champion Tezgâh Ligi 2025/26"},"shema":"zlata","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"prvak":"Mini league champion Ofis United 2024/25"},"shema":"srebrna","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"prvak":"Mini league champion Kanepe Kupası 2025/26"},"shema":"zelena","izdelek":"pulover-po-meri"}]},"uk":{"ime":"Чемпіон міні-ліги","opis":"Ти виграв міні-лігу, і всі в чаті про це знають — тепер вони це ще й побачать. Напис із твоєю лігою та сезоном ми складаємо самі, з результатів.","primeri":[{"barva":"Črna","polja":{"prvak":"Mini league champion Ліга біля стійки 2025/26"},"shema":"zlata","izdelek":"majica-po-meri"},{"barva":"Bela","polja":{"prvak":"Mini league champion Офіс Юнайтед 2024/25"},"shema":"srebrna","izdelek":"majica-po-meri"},{"barva":"Črna","polja":{"prvak":"Mini league champion Кубок Дивана 2025/26"},"shema":"zelena","izdelek":"pulover-po-meri"}]}}$p$::jsonb,
