ként hagyja el a pályát.","primeri":[{"barva":"Ena velikost","polja":{"ime":"MOLNÁR"},"shema":"kapetanska","izdelek":"trak-po-meri"},{"barva":"Ena velikost","polja":{"ime":"FARKAS"},"shema":"klasika","izdelek":"trak-po-meri"},{"barva":"Ena velikost","polja":{"ime":"PAPP"},"shema":"nocna","izdelek":"trak-po-meri"}]},"hy":{"ime":"Ավագի թևկապ","opis":"Թևկապ՝ մեծ «C»-ով և անունով։ Նրա համար, ով մրցավարին դիմում է անունով և վերջինն է լքում դաշտը։","primeri":[{"barva":"Ena velikost","polja":{"ime":"ՄԱՐԳԱՐՅԱՆ"},"shema":"kapetanska","izdelek":"trak-po-meri"},{"barva":"Ena velikost","polja":{"ime":"ՂԱԶԱՐՅԱՆ"},"shema":"klasika","izdelek":"trak-po-meri"},{"barva":"Ena velikost","polja":{"ime":"ԲԱՂԴԱՍԱՐՅԱՆ"},"shema":"nocna","izdelek":"trak-po-meri"}]},"lv":{"ime":"Kapteiņa apsējs","opis":"Apsējs ar lielu “C” un vārdu. Tam, kurš uzrunā tiesnesi vārdā un pēdējais atstāj laukumu.","primeri":[{"barva":"Ena velikost","polja":{"ime":"PĒTERSONS"},"shema":"kapetanska","izdelek":"trak-po-meri"},{"barva":"Ena velikost","polja":{"ime":"KLAVIŅŠ"},"shema":"klasika","izdelek":"trak-po-meri"},{"barva":"Ena velikost","polja":{"ime":"ZVIRBULIS"},"shema":"nocna","izdelek":"trak-po-meri"}]},"mk":{"ime":"Капитенска лента","opis":"Лента со големо „C“ и име. За оној што го вика судијата по име и последен го напушта теренот.","primeri":[{"barva":"Ena velikost","polja":{"ime":"ИЛИЕВСКИ"},"shema":"kapetanska","izdelek":"trak-po-meri"},{"barva":"Ena velikost","polja":{"ime":"СТОЈКОВСКИ"},"shema":"klasika","izdelek":"trak-po-meri"},{"barva":"Ena velikost","polja":{"ime":"ЃОРГИЕВ"},"shema":"nocna","izdelek":"trak-po-meri"}]},"pl":{"ime":"Opaska kapitana","opis":"Opaska z dużym „C” i nazwiskiem. Dla tego, kto mówi do sędziego po imieniu i ostatni schodzi z boiska.","primeri":[{"barva":"Ena velikost","polja":{"ime":"MAZUR"},"shema":"kapetanska","izdelek":"trak-po-meri"},{"barva":"Ena velikost","polja":{"ime":"JANKOWSKI"},"shema":"klasika","izdelek":"trak-po-meri"},{"barva":"Ena velikost","polja":{"ime":"GRA